// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"rabeprazol":{"wirkmechanismus":"Senkt die Bildung von Magensäure stark und anhaltend. Rabeprazol ist eine Vorstufe (Prodrug), die sich in den sauren Kanälchen der Belegzellen anreichert und dort in die aktive Sulfenamid-Form umgewandelt wird. Diese bindet fest an die H+/K+-ATPase (Protonenpumpe) und blockiert so den letzten Schritt der Säurebildung, unabhängig vom auslösenden Reiz. Die Wirkung hält an, bis neue Pumpen gebildet sind; abgebaut wird Rabeprazol überwiegend nicht-enzymatisch und nur zum Teil über CYP2C19 und CYP3A4.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Schlaflosigkeit","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen","Verstopfung, Blähungen","Gutartige Magenpolypen (Drüsenkörperzysten)","Infektionen, Husten, Rachen- und Nasenschleimhautentzündung","Rücken- und andere Schmerzen, Schwäche, grippeähnliche Beschwerden"],"gelegentlich":["Nervosität, Schläfrigkeit","Dyspepsie (Verdauungsbeschwerden), Mundtrockenheit, Aufstossen","Hautausschlag, Hautrötung","Muskel- und Gelenkschmerzen, Beinkrämpfe","Knochenbrüche (Hüfte, Handgelenk, Wirbelsäule)","Harnwegsinfekt","Erhöhte Leberwerte"],"selten":["Blutbildveränderungen (Neutropenie, Leukopenie, Thrombozytopenie)","Überempfindlichkeitsreaktionen","Depression","Sehstörungen","Geschmacksstörungen, Mundschleimhautentzündung","Leberentzündung, Gelbsucht, hepatische Enzephalopathie bei Leberzirrhose","Interstitielle Nephritis (Nierenentzündung)","Juckreiz, Schwitzen, blasenbildende Hautreaktionen"],"sehrSelten":["Erythema multiforme, Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautreaktionen)"],"unbekannt":["Hyponatriämie (Natriummangel)","Hypomagnesiämie (Magnesiummangel), dadurch auch Kalium- oder Calciummangel","Verwirrtheit","Periphere Ödeme (Wassereinlagerungen)","Gynäkomastie (Brustvergrösserung beim Mann)","Subakuter kutaner Lupus erythematodes"]},"schwangerschaft":"Kontraindiziert, da keine ausreichenden Erfahrungen vorliegen.","stillzeit":"Kontraindiziert; ob Rabeprazol in die Muttermilch übergeht, ist nicht bekannt.","hinweise":["Tabletten ganz schlucken, nicht zerkauen oder zerbrechen; bei einmal täglicher Einnahme morgens vor dem Frühstück.","Eine Langzeitbehandlung regelmässig ärztlich überprüfen lassen (Magnesium, Vitamin B12).","Nach längerer Einnahme nicht abrupt absetzen – vorübergehend verstärkte Säurebildung (Rebound) möglich."],"darreichung":["Magensaftresistente Tabletten"]},"racecadotril":{"wirkmechanismus":"Vermindert die übermässige Abgabe von Wasser und Salzen in den Darm, ohne die Darmbewegung zu bremsen. Racecadotril ist ein Prodrug, das im Körper rasch zum Wirkstoff Thiorphan umgewandelt wird. Thiorphan hemmt das Enzym Enkephalinase (neutrale Endopeptidase) in der Darmschleimhaut, sodass körpereigene Enkephaline länger wirken. Diese senken über Delta-Opioidrezeptoren die krankhaft gesteigerte Sekretion, ohne die normale Sekretion oder die Darmpassage zu beeinflussen.","nebenwirkungen":{"haeufig":["Kopfschmerzen"],"gelegentlich":["Hautausschlag","Hautrötung (Erythem)"],"unbekannt":["Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Nesselsucht (Urtikaria)","Erythema multiforme und andere schwere Hautreaktionen","Juckreiz"]},"schwangerschaft":"Nicht empfohlen (keine ausreichenden Daten).","stillzeit":"Nicht empfohlen (nicht bekannt, ob Racecadotril in die Muttermilch übergeht).","hinweise":["Wichtigste Massnahme bei Durchfall ist der Ersatz von Flüssigkeit und Salzen, besonders bei Säuglingen und Kindern (Rehydratationslösung).","Kapseln möglichst vor den Mahlzeiten einnehmen; Granulat in Nahrung, Wasser oder im Schoppen verrühren.","Behandlung fortsetzen, bis zwei normale Stuhlgänge aufgetreten sind, jedoch nicht länger als 7 Tage.","Bei Schwellungen im Gesicht oder Hautausschlag sofort absetzen und ärztlichen Rat einholen."],"darreichung":["Kapseln","Granulat (Beutel) für Säuglinge und Kinder"]},"raloxifen":{"wirkmechanismus":"Wirkt am Knochen wie ein Östrogen und bremst den Knochenabbau, ohne Brust und Gebärmutter zu stimulieren. Raloxifen ist ein selektiver Östrogenrezeptor-Modulator: Am Knochen und im Fettstoffwechsel wirkt es östrogenartig (agonistisch), an Brust- und Gebärmuttergewebe blockierend (antagonistisch). Es erhöht die Knochenmineraldichte und senkt das Risiko für Wirbelkörperbrüche; eine Senkung von Hüftbrüchen ist nicht belegt. Das LDL-Cholesterin sinkt leicht.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Grippeähnliche Beschwerden"],"haeufig":["Wadenkrämpfe","Periphere Ödeme (Wassereinlagerungen in den Beinen)","Kopfschmerzen, einschliesslich Migräne","Leichte Brustbeschwerden (Spannen, Schmerzen)"],"gelegentlich":["Venöse Thromboembolien (tiefe Venenthrombose, Lungenembolie, Netzhautvenenthrombose)","Oberflächliche Venenentzündung"],"unbekannt":["Tödlicher Schlaganfall bei Frauen mit erhöhtem Herz-Kreislauf-Risiko","Thrombozytopenie (Mangel an Blutplättchen)","Magen-Darm-Beschwerden (Übelkeit, Erbrechen, Bauchschmerzen)","Hautausschlag","Blutdruckanstieg"]},"schwangerschaft":"Kontraindiziert; Raloxifen ist nur für Frauen nach den Wechseljahren bestimmt.","stillzeit":"Kontraindiziert.","hinweise":["Vor Operationen oder längerer Bettlägerigkeit mindestens 3 Tage vorher pausieren.","Bei Schwellung, Schmerzen oder Rötung eines Beins, plötzlicher Atemnot oder Brustschmerzen sofort ärztliche Hilfe holen (Thrombose, Lungenembolie).","Auf ausreichende Calcium- und Vitamin-D-Zufuhr achten.","Raloxifen lindert keine Hitzewallungen, sondern kann sie verstärken."],"darreichung":["Filmtabletten"]},"raltegravir":{"wirkmechanismus":"Verhindert, dass das HI-Virus sein Erbgut in die menschlichen Zellen einbauen kann. Raltegravir hemmt die Integrase von HIV-1, und zwar den Strangtransfer-Schritt, mit dem die virale DNA in das Erbgut der Wirtszelle eingefügt wird. Ohne diesen Einbau kann das Virus keine neuen Viruspartikel bilden. Raltegravir wird hauptsächlich über Glucuronidierung (UGT1A1) abgebaut und beeinflusst die CYP-Enzyme kaum.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel, psychomotorische Unruhe","Abnorme Träume, Albträume, Schlaflosigkeit, Verhaltensauffälligkeiten, Depression","Übelkeit, Durchfall, Bauchschmerzen, Blähungen, Erbrechen, Verdauungsbeschwerden","Verminderter Appetit","Hautausschlag","Müdigkeit, Schwäche, Fieber","Erhöhte Leberwerte, Triglyceride, Lipase und Amylase"],"gelegentlich":["Suizidgedanken und suizidales Verhalten (v. a. bei psychischer Vorerkrankung)","Stevens-Johnson-Syndrom, DRESS (schwere Überempfindlichkeitsreaktion mit Organbeteiligung)","Hepatitis, Leberversagen","Rhabdomyolyse (Muskelzerfall), Muskel- und Gelenkschmerzen","Anämie, Neutropenie, Thrombozytopenie","Immunrekonstitutionssyndrom","Herpes simplex, Gürtelrose","Nierenversagen, Nierenentzündung, Nierensteine"],"unbekannt":["Toxische epidermale Nekrolyse"]},"schwangerschaft":"Umfangreiche Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko; Raltegravir kann in der Schwangerschaft eingesetzt werden, wenn es klinisch notwendig ist.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Mit oder ohne Mahlzeit einnehmen; Filmtabletten unzerkaut schlucken.","Filmtabletten 400 mg, Filmtabletten 600 mg und Kautabletten sind nicht gegeneinander austauschbar – nur die verordnete Form und Dosierung verwenden.","Keine aluminium- oder magnesiumhaltigen Säurebinder gleichzeitig einnehmen; bei Muskelschmerzen oder -schwäche ärztlich abklären lassen."],"darreichung":["Filmtabletten","Kautabletten"]},"raltitrexed":{"wirkmechanismus":"Hemmt die Vermehrung von Krebszellen, indem es ihnen einen Baustein der DNA entzieht. Raltitrexed ist ein Folsäure-Analogon, das über den Folat-Transporter in die Zellen gelangt und dort zu Polyglutamaten umgewandelt wird. Diese hemmen direkt und spezifisch die Thymidylatsynthase, sodass kein Thymidin für die DNA-Synthese mehr gebildet wird. Weil die Polyglutamate lange in den Zellen bleiben, genügt eine Gabe alle 3 Wochen.","nebenwirkungen":{"sehrHaeufig":["Leukopenie, Neutropenie (Mangel an weissen Blutkörperchen), Anämie","Übelkeit, Erbrechen, Durchfall","Appetitlosigkeit","Schwäche (Asthenie), Müdigkeit","Erhöhte Leberwerte (meist vorübergehend)"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Mundschleimhautentzündung, Verdauungsbeschwerden, Verstopfung, Bauchschmerzen","Flüssigkeitsmangel (Dehydratation), Gewichtsverlust","Hautausschlag, Juckreiz, Haarausfall, Schwitzen","Gelenkschmerzen, Muskelkrämpfe","Kopfschmerzen, Geschmacksstörungen","Fieber, Ödeme, Infektionen (inkl. Sepsis)","Bindehautentzündung"]},"schwangerschaft":"Kontraindiziert. Frauen und Männer müssen während und bis 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Wird als Kurzinfusion alle 3 Wochen gegeben; vorher werden Blutbild sowie Leber- und Nierenwerte kontrolliert.","Keine Vitaminpräparate mit Folsäure ohne ärztliche Rücksprache einnehmen.","Bei Durchfall, Fieber oder Mundgeschwüren sofort ärztliche Hilfe holen – Gefahr schwerer Nebenwirkungen.","Schwäche und Müdigkeit können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"ramipril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II blockiert. Ramipril ist ein Prodrug, das in der Leber zu Ramiprilat aktiviert wird; dieses hemmt das Angiotensin-Konversionsenzym (ACE) lang anhaltend. Angiotensin II und Aldosteron sinken, die Gefässe weiten sich, die Niere scheidet mehr Salz und Wasser aus, und Herz, Gefässwände und Nierenkörperchen werden langfristig entlastet. Weil ACE auch Bradykinin abbaut, steigt dessen Spiegel – das erklärt Reizhusten und Angioödeme.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Hypotonie (tiefer Blutdruck), auch beim Aufstehen; Synkope (Ohnmacht)","Trockener Reizhusten, Bronchitis, Nasennebenhöhlenentzündung, Atemnot","Magen-Darm-Entzündung, Verdauungsstörungen, Bauchbeschwerden, Durchfall, Übelkeit, Erbrechen","Hautausschlag","Muskelkrämpfe, Muskelschmerzen","Brustschmerzen, Müdigkeit","Hyperkaliämie (erhöhtes Kalium)"],"gelegentlich":["Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen; sehr selten lebensbedrohlich), intestinales Angioödem","Durchblutungsstörung des Herzens mit Angina pectoris oder Herzinfarkt, beschleunigter Puls, Herzrhythmusstörungen, Herzklopfen, Ödeme","Depressive Verstimmung, Angst, Nervosität, Schlafstörungen, Kribbeln, Geschmacksstörungen, Sehstörungen","Bronchospasmus, verstopfte Nase","Pankreatitis (Bauchspeicheldrüsenentzündung), Mundtrockenheit, Verstopfung","Nierenfunktionsstörung bis akutes Nierenversagen, Anstieg von Kreatinin und Harnstoff","Erhöhte Leber- und Bilirubinwerte","Juckreiz, vermehrtes Schwitzen, Gelenkschmerzen, Erektionsstörungen, verminderte Libido, Fieber"],"selten":["Neutropenie bis Agranulozytose, Abfall von roten Blutkörperchen, Hämoglobin und Blutplättchen","Verwirrtheit, Zittern, Gleichgewichtsstörungen","Hörstörungen, Ohrensausen, Bindehautentzündung","Vaskulitis (Gefässentzündung), Durchblutungsstörungen","Cholestatische Gelbsucht, Leberschädigung","Exfoliative Dermatitis, Nesselsucht, Nagelablösung"],"sehrSelten":["Lichtempfindlichkeit (Photosensibilität)"],"unbekannt":["Knochenmarkversagen, Panzytopenie, hämolytische Anämie","Anaphylaktische Reaktionen","Hyponatriämie (Natriummangel), SIADH","Akutes Leberversagen, Hepatitis","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme, Pemphigus","Durchblutungsstörung im Gehirn, Raynaud-Syndrom","Aphthen (Mundgeschwüre), Haarausfall, Verschlechterung einer Psoriasis","Brustvergrösserung beim Mann"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten fehlen; besser untersuchte Alternativen wählen, besonders bei Neugeborenen und Frühgeborenen.","hinweise":["Bei Schwellung von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notruf wählen (Angioödem, auch nach langer Einnahme möglich).","Ein anhaltender trockener Reizhusten ist eine typische Nebenwirkung – ärztlich besprechen, nicht eigenmächtig absetzen.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel und Kaliumpräparate nur nach ärztlicher Rücksprache.","Bei starkem Durchfall, Erbrechen oder Flüssigkeitsmangel ärztlich klären, ob die Einnahme vorübergehend pausiert werden soll."],"darreichung":["Tabletten"]},"ramucirumab":{"wirkmechanismus":"Hemmt die Bildung neuer Blutgefässe, die ein Tumor zum Wachsen braucht. Ramucirumab ist ein humaner IgG1-Antikörper, der spezifisch an den VEGF-Rezeptor 2 bindet und so dessen Aktivierung durch die Wachstumsfaktoren VEGF-A, VEGF-C und VEGF-D blockiert. Dadurch werden Vermehrung und Wanderung von Gefässwandzellen gehemmt und die Blutversorgung des Tumors vermindert.","nebenwirkungen":{"sehrHaeufig":["Bluthochdruck","Periphere Ödeme (Wassereinlagerungen)","Durchfall, Bauchschmerzen","Kopfschmerzen","Proteinurie (Eiweiss im Urin)","Nasenbluten","Neutropenie und Thrombozytopenie (in Kombination mit Chemotherapie)","Stomatitis (Mundschleimhautentzündung), Müdigkeit"],"haeufig":["Arterielle Thromboembolien (z. B. Herzinfarkt, Schlaganfall)","Magen-Darm-Blutungen","Hypokaliämie, Hyponatriämie (Kalium- und Natriummangel)","Darmverschluss","Hautausschlag","Infusionsreaktionen","Hypothyreose (Schilddrüsenunterfunktion)"],"gelegentlich":["Magen-Darm-Perforation (Durchbruch)","Nephrotisches Syndrom"],"selten":["Thrombotische Mikroangiopathie","Posteriores reversibles Enzephalopathie-Syndrom (PRES)"],"unbekannt":["Aneurysmen und Arteriendissektionen (Gefässaussackungen und -einrisse)","Hämangiome (Blutschwämmchen)","Herzinsuffizienz"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt klar: Die Hemmung der Gefässneubildung kann das Ungeborene schädigen. Frauen im gebärfähigen Alter verhüten während der Behandlung und bis 3 Monate danach.","stillzeit":"Während der Behandlung und mindestens 3 Monate nach der letzten Dosis nicht stillen.","hinweise":["Blutdruck regelmässig messen; der Urin wird auf Eiweiss kontrolliert.","Vor geplanten Operationen die Behandlung ärztlich pausieren lassen (Wundheilung).","Starke Bauchschmerzen, schwarzen Stuhl, Bluterbrechen, Brustschmerzen, Lähmungen oder starke Kopfschmerzen sofort melden.","Vor jeder Infusion wird ein Antihistaminikum gegeben (Vorbeugung von Infusionsreaktionen)."],"darreichung":["Infusionskonzentrat"]},"ranibizumab":{"wirkmechanismus":"Hemmt das Wachstum undichter, krankhafter Blutgefässe in der Netzhaut. Ranibizumab ist ein humanisiertes Antikörperfragment (Fab), das alle Formen des Wachstumsfaktors VEGF-A bindet. Dadurch kann VEGF-A nicht mehr an seine Rezeptoren VEGFR-1 und VEGFR-2 andocken; Gefässneubildung, Gefässdurchlässigkeit und Netzhautschwellung nehmen ab. Da es in den Glaskörper gespritzt wird und im Blut rasch abgebaut wird, ist die Wirkung im übrigen Körper gering.","nebenwirkungen":{"sehrHaeufig":["Entzündung im Glaskörper (Vitritis), Glaskörperabhebung, Glaskörpertrübungen (Mouches volantes)","Netzhautblutung, Bindehautblutung","Augenschmerzen, Augenreizung, Fremdkörpergefühl, Augenrötung","Sehstörungen","Erhöhter Augeninnendruck","Kopfschmerzen","Nasen-Rachen-Entzündung","Gelenkschmerzen"],"haeufig":["Netzhautablösung oder -riss, Riss des retinalen Pigmentepithels","Uveitis, Iritis (Entzündung im Augeninneren)","Grauer Star (Katarakt), Glaskörperblutung","Verschwommenes Sehen, verminderte Sehschärfe","Allergische Reaktionen (Ausschlag, Nesselsucht, Juckreiz)","Blutarmut (Anämie)","Angst, Husten, Übelkeit","Harnwegsinfekt"],"gelegentlich":["Endophthalmitis (schwere Infektion im Augeninneren)","Erblindung","Eiter- oder Blutansammlung in der vorderen Augenkammer","Hornhautveränderungen (Ödem, Ablagerungen)","Schmerzen und Reizung an der Einstichstelle"],"unbekannt":["Arterielle Thromboembolien wie Schlaganfall oder Herzinfarkt (theoretisches Risiko von VEGF-Hemmern)"]},"schwangerschaft":"Nicht anwenden, ausser der erwartete Nutzen überwiegt das mögliche Risiko für das Ungeborene. Frauen im gebärfähigen Alter verhüten während der Behandlung zuverlässig.","stillzeit":"Stillen wird während der Behandlung vorsichtshalber nicht empfohlen.","hinweise":["Bei zunehmenden Augenschmerzen, Rötung, Lichtempfindlichkeit, Schleier- oder Schattensehen in den Tagen nach der Injektion sofort die Augenärztin oder den Augenarzt aufsuchen.","Nach der Injektion kann das Sehen vorübergehend gestört sein – bis zur Erholung nicht Auto fahren.","Kontroll- und Injektionstermine einhalten; Behandlungslücken können das Sehvermögen gefährden."],"darreichung":["Injektionslösung zur Injektion in den Glaskörper (Durchstechflasche, Fertigspritze)"]},"ranolazin":{"wirkmechanismus":"Verbessert die Sauerstoffbilanz des Herzmuskels bei Durchblutungsstörungen, ohne Puls und Blutdruck wesentlich zu verändern. Ranolazin hemmt den späten Natriumeinstrom (späten Natriumstrom) in die Herzmuskelzellen, der bei Sauerstoffmangel verstärkt ist. Dadurch sinkt die Überladung der Zellen mit Natrium und in der Folge mit Calcium; der Herzmuskel kann sich in der Diastole besser entspannen, Wandspannung und Sauerstoffverbrauch nehmen ab.","nebenwirkungen":{"haeufig":["Schwindel","Kopfschmerzen","Obstipation (Verstopfung)","Übelkeit, Erbrechen","Asthenie (Schwächegefühl)"],"gelegentlich":["Synkope (Ohnmacht), Schwindel beim Aufstehen","Sehstörungen (verschwommenes Sehen, Doppelbilder), Drehschwindel, Ohrensausen","Verwirrtheit, Halluzinationen","Hypotonie (tiefer Blutdruck), Hitzewallungen","Atemnot, Husten","Periphere Ödeme (Wassereinlagerungen)","Anstieg von Kreatinin und Harnstoff im Blut","QT-Verlängerung im EKG"],"selten":["Akutes Nierenversagen","Angioödem (Schwellung von Gesicht und Rachen)","Harnverhalt"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn unbedingt erforderlich.","stillzeit":"Nicht stillen – ein Übergang in die Muttermilch ist nicht bekannt, ein Risiko kann nicht ausgeschlossen werden.","hinweise":["Retardtabletten ganz schlucken, nicht teilen, zerkleinern oder zerkauen.","Keinen Grapefruitsaft trinken.","Nicht zur Behandlung eines akuten Angina-pectoris-Anfalls geeignet – dafür Nitroglycerin verwenden.","Kann Schwindel und Sehstörungen verursachen – Vorsicht beim Autofahren."],"darreichung":["Retardtabletten"]},"rasagilin":{"wirkmechanismus":"Verlängert die Wirkung des körpereigenen Dopamins im Gehirn. Rasagilin hemmt irreversibel und selektiv die Monoaminoxidase B (MAO-B), das Enzym, das Dopamin im Gehirn abbaut. Dadurch steigt die Dopaminkonzentration im Striatum, was die Parkinson-Beschwerden lindert und Wirkungsschwankungen von Levodopa vermindert. In der empfohlenen Dosis bleibt die MAO-A weitgehend unbeeinflusst, so dass in der Regel keine tyraminarme Diät nötig ist.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Dyskinesien (Überbewegungen, bei Kombination mit Levodopa)"],"haeufig":["Grippeähnliche Beschwerden, Schnupfen","Depression, Halluzinationen","Schwindel, Gleichgewichtsstörungen","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Angina pectoris (Brustenge)","Bauchschmerzen, Verstopfung, Übelkeit, Mundtrockenheit","Gelenk- und Nackenschmerzen, Stürze","Hautkrebs (Karzinom der Haut)"],"gelegentlich":["Schlaganfall","Herzinfarkt","Malignes Melanom (schwarzer Hautkrebs)","Verwirrtheit","Blasiger Hautausschlag"],"unbekannt":["Serotoninsyndrom (v. a. zusammen mit Antidepressiva)","Bluthochdruck","Impulskontrollstörungen (Spielsucht, Kaufsucht, Essattacken, gesteigertes sexuelles Verlangen)","Übermässige Tagesschläfrigkeit, plötzliches Einschlafen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen. Vorsichtshalber in der Schwangerschaft nicht anwenden.","stillzeit":"Rasagilin kann die Milchbildung hemmen; ob es in die Muttermilch übergeht, ist nicht bekannt. Nur nach ärztlicher Abwägung.","hinweise":["Einmal täglich einnehmen, unabhängig von den Mahlzeiten.","Vor der Einnahme rezeptfreier Husten-, Schnupfen- oder Erkältungsmittel sowie von Johanniskraut in der Apotheke nachfragen.","Haut regelmässig auf auffällige Muttermale kontrollieren lassen.","Bei Tagesschläfrigkeit nicht Auto fahren; Angehörige sollten auf Spiel- oder Kaufsucht achten."],"darreichung":["Tabletten"]},"ravulizumab":{"wirkmechanismus":"Blockiert einen Teil des Komplementsystems, einer Abwehrkaskade im Blut, die bei diesen Krankheiten eigene Blutzellen, Gefässe oder Nerven angreift. Ravulizumab ist ein aus Eculizumab weiterentwickelter humanisierter monoklonaler Antikörper gegen das Komplementprotein C5 und verhindert die Bildung von C5a und des Membranangriffskomplexes. Gezielte Aminosäure-Austausche lassen ihn sich im Endosom vom C5 lösen und über den neonatalen Fc-Rezeptor ins Blut zurückkehren; dadurch ist die Halbwertszeit etwa viermal länger. Wie bei Eculizumab steigt das Risiko für Meningokokken-Infektionen stark.","nebenwirkungen":{"sehrHaeufig":["Infekte der oberen Atemwege, Nasen-Rachen-Entzündung","Kopfschmerzen"],"haeufig":["Durchfall, Übelkeit, Erbrechen, Bauchschmerzen","Schwindel","Nesselsucht, Juckreiz, Hautausschlag","Gelenk-, Rücken- und Muskelschmerzen, Muskelkrämpfe","Fieber, grippeähnliche Beschwerden, Müdigkeit","Infusionsreaktionen"],"gelegentlich":["Meningokokken-Infektionen (Hirnhautentzündung, Blutvergiftung)","Anaphylaxie und Überempfindlichkeitsreaktionen","Schüttelfrost"]},"schwangerschaft":"Nur nach ärztlicher Nutzen-Risiko-Abwägung. Frauen im gebärfähigen Alter sollen während der Behandlung und bis 8 Monate danach zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 8 Monate nach der letzten Dosis nicht stillen bzw. nur nach ärztlicher Abwägung.","hinweise":["Patientenkarte immer mitführen. Bei Fieber, Kopfschmerzen mit Übelkeit, Nackensteifigkeit, Lichtempfindlichkeit oder Hautflecken sofort den Notfall aufsuchen.","Meningokokken-Impfung mindestens 2 Wochen vor Beginn, sonst vorbeugende Antibiotika; Auffrischimpfungen gemäss Plan.","Infusionstermine (alle 8 Wochen) strikt einhalten und nicht eigenmächtig absetzen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"reboxetin":{"wirkmechanismus":"Steigert Antrieb und Stimmung, indem es die Menge des Botenstoffs Noradrenalin im Gehirn erhöht. Reboxetin hemmt selektiv den Noradrenalin-Transporter; auf die Wiederaufnahme von Serotonin und auf Muskarin-, Histamin- oder Alpha-Rezeptoren wirkt es kaum. Es wird in der Leber vor allem über CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Mundtrockenheit","Obstipation (Verstopfung)","Vermehrtes Schwitzen"],"haeufig":["Kopfschmerzen, Schwindel","Unruhe, Angst, Sitzunruhe (Akathisie)","Herzrasen, Herzklopfen","Blutdruckanstieg oder Blutdruckabfall beim Aufstehen","Übelkeit, Erbrechen, Appetitminderung","Harnverhalt, Gefühl unvollständiger Blasenentleerung, Harnwegsinfekte","Erektionsstörungen, Schmerzen beim Samenerguss","Missempfindungen, Geschmacks- und Sehstörungen"],"gelegentlich":["Pupillenerweiterung (Mydriasis)","Drehschwindel (Vertigo)"],"unbekannt":["Hyponatriämie (Natriummangel)","Aggressivität, Halluzinationen, Reizbarkeit","Suizidgedanken und suizidales Verhalten","Kalte Hände und Füsse, Raynaud-Syndrom","Allergische Hautreaktionen","Hodenschmerzen"]},"schwangerschaft":"Nicht empfohlen; nur bei zwingender Notwendigkeit nach ärztlicher Abwägung.","stillzeit":"Geht in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung, der Säugling ist zu beobachten.","hinweise":["Die stimmungsaufhellende Wirkung setzt erst nach 2–3 Wochen ein.","Bei Problemen beim Wasserlassen ärztlich Rücksprache nehmen.","Nicht abrupt absetzen, sondern schrittweise nach ärztlicher Anweisung."],"darreichung":["Tabletten"]},"regadenoson":{"wirkmechanismus":"Ahmt eine körperliche Belastung nach, indem es die Herzkranzgefässe für wenige Minuten stark erweitert. Regadenoson aktiviert gezielt den Adenosin-A2A-Rezeptor der Koronargefässe; die Durchblutung gesunder Gefässe steigt deutlich, verengte Gefässe können nicht mitziehen. Dieser Unterschied wird in der Szintigrafie sichtbar. Die Wirkung tritt innert 1–4 Minuten ein und klingt rasch wieder ab.","nebenwirkungen":{"sehrHaeufig":["Atemnot (Dyspnoe)","Kopfschmerzen","Gesichtsrötung (Flush)","Brustschmerzen oder Druckgefühl in der Brust","Schwindel","EKG-Veränderungen (ST-Senkung)"],"haeufig":["Angina pectoris","AV-Block (Reizleitungsstörung)","Herzrasen, Herzklopfen","Hypotonie (Blutdruckabfall)","Übelkeit, Erbrechen, Magen-Darm-Beschwerden","Schmerzen in Kiefer, Nacken, Rücken oder Armen","Missempfindungen (Kribbeln), Geschmacksstörung","Schwitzen, Unwohlsein"],"gelegentlich":["Synkope (Ohnmacht)","Bradykardie (langsamer Puls)","Bronchospasmus (Verkrampfung der Atemwege), pfeifende Atmung"],"unbekannt":["Herzinfarkt, Herzstillstand, gefährliche Herzrhythmusstörungen","Krampfanfälle","Schlaganfall, TIA","Vorhofflimmern","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Nach der Gabe mindestens 10 Stunden nicht stillen und die abgepumpte Milch verwerfen.","hinweise":["Mindestens 12 Stunden vor der Untersuchung keinen Kaffee, Tee, Cola, Energydrinks oder Schokolade zu sich nehmen.","Über alle Medikamente informieren, besonders Theophyllin und Dipyridamol.","Wird nur im Spital oder in spezialisierten Zentren unter Herz- und Blutdrucküberwachung gegeben."],"darreichung":["Injektionslösung (Fertigspritze)"]},"regorafenib":{"wirkmechanismus":"Hemmt das Wachstum von Tumoren und ihre Blutversorgung. Regorafenib blockiert zahlreiche Kinasen: Rezeptoren der Gefässneubildung (VEGFR-1 bis -3, TIE-2), krebsfördernde Kinasen (KIT, RET, RAF-1, BRAF) und Kinasen der Tumorumgebung (PDGFR, FGFR). Seine aktiven Metaboliten M-2 und M-5 tragen wesentlich zur Wirkung bei.","nebenwirkungen":{"sehrHaeufig":["Infektionen","Blutarmut, Mangel an Blutplättchen","Appetitverlust, Gewichtsabnahme, Müdigkeit, Schwäche, Fieber","Kopfschmerzen, Schmerzen","Blutungen, Bluthochdruck","Durchfall, Stomatitis (Entzündung der Mundschleimhaut), Heiserkeit","Hand-Fuss-Hautreaktion, Hautausschlag","Erhöhtes Bilirubin"],"haeufig":["Mangel an weissen Blutkörperchen","Hypothyreose (Schilddrüsenunterfunktion)","Elektrolytstörungen (tiefes Kalium, Phosphat, Calcium, Natrium, Magnesium), Flüssigkeitsmangel","Zittern, periphere Neuropathie (Kribbeln, Taubheit)","Geschmacksstörungen, Mundtrockenheit, Sodbrennen","Erhöhte Leberwerte","Haarausfall, trockene Haut","Eiweiss im Urin (Proteinurie)"],"gelegentlich":["Schwere Leberschäden","Herzinfarkt, Durchblutungsstörungen des Herzmuskels","Hypertensive Krise (Blutdruckentgleisung)","Magen-Darm-Durchbruch (Perforation), Fisteln","Pankreatitis (Bauchspeicheldrüsenentzündung)","Erythema multiforme, Überempfindlichkeitsreaktionen"],"selten":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Keratoakanthom, Plattenepithelkarzinom der Haut"],"unbekannt":["Aneurysmen und Gefässwandeinrisse (Dissektionen)"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nur bei zwingender Notwendigkeit. Frauen und Männer müssen während der Behandlung und bis 8 Wochen danach zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Täglich zur gleichen Zeit nach einer leichten, fettarmen Mahlzeit einnehmen; meist 3 Wochen Einnahme und 1 Woche Pause.","Keine Grapefruit, kein Johanniskraut.","Leberwerte und Blutdruck werden regelmässig kontrolliert; Gelbsucht, dunklen Urin oder Blutungen sofort melden.","Hände und Füsse pflegen (Feuchtigkeitscreme, bequeme Schuhe); Hautreaktionen früh melden."],"darreichung":["Filmtabletten"]},"relugolix":{"wirkmechanismus":"Senkt rasch die Bildung der Geschlechtshormone Testosteron bzw. Östrogen. Relugolix blockiert als nicht-peptidischer Antagonist die GnRH-Rezeptoren der Hirnanhangdrüse, sodass weniger LH und FSH ausgeschüttet werden – anders als GnRH-Agonisten ohne anfänglichen Hormonanstieg. Beim Mann sinkt das Testosteron innert weniger Tage auf Kastrationsniveau, was das Wachstum hormonabhängiger Prostatakrebszellen bremst. In Ryeqo mildern niedrig dosiertes Estradiol und Norethisteronacetat Hitzewallungen und Knochenabbau durch den Östrogenmangel.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen (unter Ryeqo häufig)","Muskel- und Gelenkschmerzen","Müdigkeit","Durchfall","Verstopfung"],"haeufig":["Kopfschmerzen, Schwindel","Schlaflosigkeit, depressive Verstimmung","Blutarmut (Anämie)","Bluthochdruck","Übelkeit","Vermehrtes Schwitzen, Hautausschlag","Brustvergrösserung beim Mann, verminderte Libido","Ryeqo: Gebärmutterblutungen, Haarausfall"],"gelegentlich":["Herzinfarkt","Nesselsucht, Angioödem (Schwellung von Haut und Schleimhäuten)","Abnahme der Knochendichte (Osteoporose)"],"unbekannt":["QT-Verlängerung im EKG"]},"schwangerschaft":"Kontraindiziert; Relugolix kann zu Fehlgeburten führen. Unter Ryeqo ist im ersten Behandlungsmonat eine nichthormonale Verhütung nötig. Männer unter Orgovyx mit Partnerinnen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Ryeqo ist in der Stillzeit kontraindiziert.","hinweise":["Täglich etwa zur gleichen Zeit einnehmen; Orgovyx beginnt mit einer höheren Startdosis am ersten Tag.","Ryeqo: andere hormonale Verhütungsmittel absetzen und im ersten Monat zusätzlich nichthormonal (z. B. Kondom) verhüten. Ausbleibende oder schwächere Blutungen erschweren das Erkennen einer Schwangerschaft.","Vor neuen Medikamenten, besonders Antibiotika aus der Makrolid-Gruppe und Herzmitteln, Ärztin, Arzt oder Apotheke fragen.","Knochendichte und bei Herzrisiko das EKG gemäss ärztlicher Anordnung kontrollieren lassen."],"darreichung":["Filmtabletten"]},"remdesivir":{"wirkmechanismus":"Hemmt die Vermehrung des Coronavirus SARS-CoV-2. Remdesivir ist eine Vorstufe (Prodrug), die in den Körperzellen zum aktiven Nukleosidtriphosphat (GS-443902) umgewandelt wird. Dieses ähnelt dem Baustein ATP und wird von der viralen RNA-abhängigen RNA-Polymerase in die neu gebildete Virus-RNA eingebaut, was die Kettenverlängerung verzögert abbricht.","nebenwirkungen":{"sehrHaeufig":["Erhöhte Leberwerte (Transaminasen)"],"haeufig":["Kopfschmerzen","Übelkeit","Hautausschlag"],"selten":["Überempfindlichkeitsreaktionen","Infusionsbedingte Reaktionen (Blutdruckabfall, Herzrasen, Schüttelfrost, Atemnot)"],"unbekannt":["Anaphylaxie, anaphylaktischer Schock","Sinusbradykardie (langsamer Puls)"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn der Nutzen für die Mutter das mögliche Risiko für das Kind überwiegt.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Stillen nach ärztlicher Abwägung.","hinweise":["Wird als Infusion unter ärztlicher Überwachung verabreicht, meist im Spital.","Leberwerte und Gerinnungswerte (Prothrombinzeit) werden vor und während der Behandlung kontrolliert.","Nicht gleichzeitig mit Hydroxychloroquin oder Chloroquin anwenden."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"remibrutinib":{"wirkmechanismus":"Verhindert, dass Mastzellen und basophile Granulozyten Histamin und andere Stoffe freisetzen, die Quaddeln und Juckreiz auslösen. Remibrutinib bindet kovalent und hochselektiv an die Bruton-Tyrosinkinase (BTK) und inaktiviert sie dauerhaft. BTK ist ein Schlüsselenzym in der Signalkette des IgE-Rezeptors auf Mastzellen und Basophilen sowie des B-Zell-Rezeptors; ihre Hemmung unterdrückt die Aktivierung dieser Zellen.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege (z. B. Nasen-Rachen-Entzündung)"],"haeufig":["Blutergüsse und punktförmige Hautblutungen (Petechien)","Kopfschmerzen","Herpes-Infektionen (z. B. Lippenherpes)"],"unbekannt":["Andere leichte bis mittelschwere Schleimhautblutungen (z. B. Nasenbluten)"]},"schwangerschaft":"Nicht empfohlen: Daten beim Menschen fehlen, im Tierversuch traten bei hohen Dosen Fehlbildungen auf. Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob Remibrutinib in die Muttermilch übergeht; Stillen nur nach ärztlicher Abwägung.","hinweise":["Zweimal täglich im Abstand von etwa 12 Stunden einnehmen; Grapefruit und Grapefruitsaft meiden.","Vor Operationen und Zahneingriffen die Einnahme angeben (Pause von 3–7 Tagen).","Ungewöhnliche oder anhaltende Blutungen ärztlich melden."],"darreichung":["Filmtabletten"]},"remifentanil":{"wirkmechanismus":"Sehr starkes Schmerzmittel mit sofortigem Wirkbeginn, dessen Wirkung wenige Minuten nach Ende der Infusion abklingt. Remifentanil ist ein selektiver Agonist am µ-Opioidrezeptor. Wegen einer Esterbindung wird es von unspezifischen Esterasen in Blut und Gewebe rasch zu einem praktisch unwirksamen Abbauprodukt gespalten – unabhängig von Leber- und Nierenfunktion und von der Dauer der Infusion (kontextsensitive Halbwertszeit etwa 3–4 Minuten).","nebenwirkungen":{"sehrHaeufig":["Muskelsteifigkeit (Rigor)","Blutdruckabfall (Hypotonie)","Übelkeit","Erbrechen"],"haeufig":["Bradykardie (langsamer Puls)","Blutdruckanstieg nach der Operation","Akute Atemdepression, Apnoe (Atemstillstand)","Juckreiz","Kältezittern nach der Operation"],"gelegentlich":["Hypoxie (Sauerstoffmangel)","Verstopfung","Schmerzen nach der Operation"],"selten":["Sedierung in der Aufwachphase","Asystolie bzw. Herzstillstand, meist nach vorausgehender Bradykardie","Allergische Reaktionen bis Anaphylaxie"],"unbekannt":["Toleranz, Abhängigkeit und Entzugssymptome","Krampfanfälle","AV-Block (Reizleitungsstörung des Herzens)"]},"schwangerschaft":"Nur bei klarer Notwendigkeit. Remifentanil gelangt zum Ungeborenen; bei Gabe unter der Geburt ist beim Neugeborenen eine Atemdämpfung möglich.","stillzeit":"Nach der Gabe 24 Stunden lang nicht stillen.","hinweise":["Wird nur durch Anästhesie- oder Intensivfachpersonen mit Überwachung und Beatmungsmöglichkeit verabreicht; Gegenmittel ist Naloxon.","Nach dem Eingriff mindestens 24 Stunden kein Fahrzeug lenken, keine Maschinen bedienen und keinen Alkohol trinken."],"darreichung":["Pulver zur Herstellung einer Injektions- bzw. Infusionslösung"]},"repaglinid":{"wirkmechanismus":"Regt die Bauchspeicheldrüse kurzzeitig und passend zur Mahlzeit zur Insulinausschüttung an. Repaglinid schliesst wie die Sulfonylharnstoffe die ATP-abhängigen Kaliumkanäle der Betazellen, bindet aber an eine andere Stelle des Rezeptors. Die Wirkung setzt innerhalb von etwa 30 Minuten ein und klingt nach wenigen Stunden ab, sodass vor allem der Blutzuckeranstieg nach dem Essen gedämpft wird. Repaglinid wird über den Transporter OATP1B1 in die Leber aufgenommen und dort über CYP2C8 und CYP3A4 abgebaut.","nebenwirkungen":{"haeufig":["Hypoglykämie (Unterzuckerung)","Bauchschmerzen","Durchfall"],"selten":["Herz-Kreislauf-Erkrankungen (z. B. akutes Koronarsyndrom)"],"sehrSelten":["Allergische Reaktionen, z. B. allergische Gefässentzündung (Vaskulitis)","Vorübergehende Sehstörungen","Erbrechen, Obstipation (Verstopfung)","Leberfunktionsstörungen, erhöhte Leberwerte"],"unbekannt":["Schwere Unterzuckerung mit Bewusstlosigkeit","Übelkeit","Überempfindlichkeitsreaktionen der Haut (Juckreiz, Ausschlag, Nesselsucht)"]},"schwangerschaft":"Nicht anwenden; ein Diabetes in der Schwangerschaft wird mit Insulin behandelt.","stillzeit":"Nicht anwenden.","hinweise":["Innerhalb von 15–30 Minuten vor jeder Hauptmahlzeit einnehmen; wird eine Mahlzeit ausgelassen, auch die Tablette auslassen.","Zeichen einer Unterzuckerung kennen und Traubenzucker mitführen; Alkohol erhöht das Risiko.","Unterzuckerungen können die Fahrtüchtigkeit beeinträchtigen.","Vor Beginn neuer Medikamente (z. B. Clopidogrel, Antibiotika) die Behandlung mit Repaglinid angeben."],"darreichung":["Tabletten"]},"repotrectinib":{"wirkmechanismus":"Bremst das Wachstum von Krebszellen, die durch ein verändertes Wachstumssignal-Enzym angetrieben werden. Repotrectinib ist ein kleiner, ringförmiger (makrozyklischer) Hemmer der Tyrosinkinasen ROS1 sowie TRKA, TRKB und TRKC. Bei Tumoren mit ROS1- oder NTRK-Genfusion sind diese Kinasen dauerhaft aktiv; ihre Blockade stoppt die Zellteilung und führt zum Zelltod. Die kompakte Struktur wirkt auch gegen manche Resistenzmutationen und erreicht das Gehirn.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Dysgeusie (Geschmacksstörung)","Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Ataxie (Gangunsicherheit) und Muskelschwäche","Kognitive Störungen (Gedächtnis- und Aufmerksamkeitsprobleme)","Obstipation (Verstopfung), Übelkeit","Atemnot (Dyspnoe), Müdigkeit","Anämie (Blutarmut), erhöhte Leber- und Muskelwerte (CK)"],"haeufig":["Knochenbrüche","Pneumonitis (nicht-infektiöse Lungenentzündung)"],"unbekannt":["Hyperurikämie (erhöhte Harnsäure)","Stürze"]},"schwangerschaft":"Nicht anwenden: Eine Schädigung des ungeborenen Kindes ist zu erwarten. Frauen im gebärfähigen Alter und Männer mit Partnerin verhüten während der Behandlung und nach Therapieende gemäss ärztlicher Anweisung zuverlässig (Frauen nicht-hormonal).","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Kapseln unzerkaut mit Wasser schlucken, mit oder ohne Mahlzeit; Grapefruit meiden.","Schwindel und Gangunsicherheit sind sehr häufig: Vorsicht beim Autofahren, beim Bedienen von Maschinen und wegen Sturzgefahr.","Neu auftretenden Husten, Atemnot, Knochen- oder Muskelschmerzen umgehend melden.","Alle anderen Medikamente, auch pflanzliche wie Johanniskraut, mit dem Behandlungsteam abstimmen."],"darreichung":["Kapseln"]},"resmetirom":{"wirkmechanismus":"Regt den Fettabbau in der Leber an und vermindert so Leberverfettung, Entzündung und Vernarbung. Resmetirom aktiviert gezielt den Schilddrüsenhormon-Rezeptor beta (THR-β), der vor allem in Leberzellen vorkommt. Dadurch werden vermehrt Fettsäuren in den Mitochondrien abgebaut und die Fettneubildung gedrosselt. Am Rezeptor THR-α, der unter anderem Herz und Knochen steuert, wirkt es kaum.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Übelkeit"],"haeufig":["Erbrechen","Verstopfung","Bauchschmerzen","Juckreiz","Schwindel"],"unbekannt":["Medikamentös bedingte Leberschädigung (Anstieg der Leberwerte)","Gallensteine, Gallenblasenentzündung"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; Anwendung während der Schwangerschaft vermeiden.","stillzeit":"Nicht bekannt, ob Resmetirom in die Muttermilch übergeht; Nutzen und Risiko ärztlich abwägen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen.","Ernährungsumstellung, Gewichtsabnahme und Bewegung bleiben die Grundlage der Behandlung.","Leberwerte werden regelmässig kontrolliert; Gelbsucht, dunklen Urin oder Oberbauchschmerzen ärztlich melden.","Die Einnahme von Statinen, Clopidogrel oder Gemfibrozil ärztlich angeben."],"darreichung":["Filmtabletten"]},"retifanlimab":{"wirkmechanismus":"Löst eine Bremse des Immunsystems, damit Abwehrzellen Krebszellen wieder bekämpfen. Retifanlimab ist ein humanisierter IgG4-Antikörper, der an den Rezeptor PD-1 auf T-Zellen bindet und dessen Aktivierung durch die Liganden PD-L1 und PD-L2 blockiert. Tumoren nutzen diese Liganden, um T-Zellen abzuschalten; die Blockade stellt die Immunantwort gegen den Tumor wieder her.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit","Juckreiz, Hautausschlag","Durchfall","Muskel- und Gelenkschmerzen"],"haeufig":["Hypothyreose, Hyperthyreose (Schilddrüsenunter- und -überfunktion)","Pneumonitis (nicht-infektiöse Lungenentzündung)","Erhöhte Leberwerte","Infusionsreaktionen","Fieber","Übelkeit","Anämie (Blutarmut)"],"unbekannt":["Kolitis (Dickdarmentzündung)","Hepatitis (Leberentzündung)","Nebenniereninsuffizienz, Hypophysitis","Typ-1-Diabetes","Nephritis (Nierenentzündung)","Myokarditis, Myositis","Abstossung transplantierter Organe"]},"schwangerschaft":"Nicht empfohlen: IgG-Antikörper gehen über die Plazenta, und die PD-1-Blockade kann die Toleranz gegenüber dem Ungeborenen stören. Frauen im gebärfähigen Alter verhüten während der Behandlung und mindestens 4 Monate danach.","stillzeit":"Während der Behandlung und mindestens 4 Monate nach der letzten Dosis nicht stillen.","hinweise":["Neue Beschwerden wie Durchfall, Husten, Atemnot, Gelbsucht, starke Müdigkeit, Kopfschmerzen oder Hautausschlag sofort melden – auch Monate nach Therapieende.","Den Patientenausweis immer bei sich tragen und allen Ärztinnen und Ärzten zeigen.","Leber-, Nieren- und Schilddrüsenwerte sowie Blutzucker werden regelmässig kontrolliert.","Kortison nicht eigenmächtig beginnen oder absetzen."],"darreichung":["Infusionskonzentrat"]},"retinol-vitamin-a":{"wirkmechanismus":"Vitamin A ist unentbehrlich für das Sehen in der Dämmerung, für gesunde Haut und Schleimhäute sowie für Wachstum und Immunabwehr. Im Auge wird es zu 11-cis-Retinal umgewandelt, das zusammen mit dem Eiweiss Opsin den Sehfarbstoff Rhodopsin bildet. Sein Stoffwechselprodukt Retinsäure steuert über Kernrezeptoren (RAR, RXR) Wachstum und Ausreifung von Zellen. Vitamin A wird in der Leber gespeichert; zu hohe Dosen reichern sich deshalb an und wirken giftig.","nebenwirkungen":{"unbekannt":["Bei Überdosierung: Kopfschmerzen, Übelkeit, Erbrechen, Schläfrigkeit","Hirndrucksteigerung (bei Säuglingen vorgewölbte Fontanelle)","Trockene, schuppende Haut, rissige Lippen, Haarausfall","Knochen- und Gelenkschmerzen","Leberschäden","Hyperkalzämie (erhöhtes Calcium)"]},"schwangerschaft":"Dosen im Bereich des Tagesbedarfs sind erlaubt. Hohe Dosen können Fehlbildungen verursachen und sind kontraindiziert; Vitamin A in der Schwangerschaft nur auf ärztliche Verordnung einnehmen.","stillzeit":"Vitamin A geht in die Muttermilch über; Dosen über dem Tagesbedarf nur nach ärztlicher Abwägung.","hinweise":["Keine weiteren Vitamin-A-haltigen Präparate ohne ärztliche Rücksprache einnehmen; auch Leber enthält sehr viel Vitamin A.","Frauen im gebärfähigen Alter: vor hoch dosierter Einnahme eine Schwangerschaft ausschliessen.","Zeichen einer Überdosierung (Kopfschmerzen, Erbrechen, Hautschuppung) ärztlich melden."],"darreichung":["Tropfen zum Einnehmen"]},"ribociclib":{"wirkmechanismus":"Bremst die Teilung hormonempfindlicher Brustkrebszellen. Ribociclib hemmt selektiv die Cyclin-abhängigen Kinasen 4 und 6 (CDK4/6); dadurch bleibt das Retinoblastom-Protein unphosphoryliert, und der Zellzyklus stoppt in der G1-Phase. Zusammen mit einer antihormonellen Therapie wird das Tumorwachstum stärker gebremst als mit der Hormontherapie allein. Ribociclib wird über CYP3A4 abgebaut und hemmt dieses Enzym selbst deutlich.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Leukopenie, Anämie, Lymphopenie","Infektionen (v. a. Harnwege und obere Atemwege)","Übelkeit, Durchfall, Erbrechen, Verstopfung, Bauchschmerzen, Stomatitis","Appetitlosigkeit","Kopfschmerzen, Schwindel","Haarausfall, Hautausschlag, Juckreiz","Müdigkeit, Rückenschmerzen, periphere Ödeme, Fieber","Erhöhte Leberwerte (ALT, AST)"],"haeufig":["Febrile Neutropenie, Thrombozytopenie","QT-Verlängerung im EKG","Synkope (Ohnmacht)","Hypokalzämie, Hypokaliämie, Hypophosphatämie","Vermehrter Tränenfluss, trockene Augen","Trockene Haut, Hautrötung, Vitiligo (Weissfleckenkrankheit)","Leberschädigung (Hepatotoxizität)","Erhöhtes Kreatinin"],"unbekannt":["Interstitielle Lungenerkrankung, Pneumonitis","Toxische epidermale Nekrolyse, DRESS (schwere Arzneimittelreaktionen)"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen müssen während und mindestens 21 Tage nach der letzten Dosis sicher verhüten.","stillzeit":"Während der Behandlung und mindestens 21 Tage nach der letzten Dosis nicht stillen.","hinweise":["Bei fortgeschrittenem Brustkrebs Einnahme an 21 Tagen, danach 7 Tage Pause; einmal täglich, möglichst morgens, mit oder ohne Mahlzeit.","EKG vor Beginn und in den ersten Behandlungszyklen; Leberwerte und Blutbild werden regelmässig kontrolliert.","Grapefruit, Granatapfel und deren Säfte meiden; vor jedem neuen Medikament (auch rezeptfrei) Wechselwirkungen prüfen lassen.","Herzklopfen, Ohnmacht, Gelbsucht oder dunkler Urin sofort melden."],"darreichung":["Filmtabletten"]},"rifabutin":{"wirkmechanismus":"Tötet Mykobakterien ab, indem es das Ablesen ihrer Erbinformation blockiert. Rifabutin hemmt wie Rifampicin die bakterielle DNA-abhängige RNA-Polymerase und verhindert so die Bildung bakterieller Eiweisse. Es wirkt auch gegen den Mycobacterium-avium-Komplex und gegen manche Rifampicin-resistente Tuberkulosestämme. Rifabutin induziert die Leberenzyme (vor allem CYP3A4), allerdings schwächer als Rifampicin.","nebenwirkungen":{"haeufig":["Leukopenie, Neutropenie (Mangel an weissen Blutkörperchen), Anämie","Übelkeit","Hautausschlag","Fieber","Gelenk- und Muskelschmerzen"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Überempfindlichkeitsreaktionen, Bronchospasmus, Eosinophilie","Erbrechen","Erhöhte Leberwerte, Gelbsucht"],"unbekannt":["Uveitis (Augenentzündung), Hornhautablagerungen","Agranulozytose, Panzytopenie","Clostridioides-difficile-Kolitis (schwerer Durchfall)","Anaphylaktischer Schock","Hepatitis","Hautverfärbung"]},"schwangerschaft":"Laut Fachinformation wegen ungenügender Erfahrung nicht anwenden; bei Tuberkulose in der Schwangerschaft entscheidet eine spezialisierte Ärztin oder ein spezialisierter Arzt.","stillzeit":"Wegen ungenügender Erfahrung nicht anwenden bzw. abstillen.","hinweise":["Urin, Schweiss, Tränen und Haut können sich orange-braun verfärben; weiche Kontaktlinsen können dauerhaft verfärbt werden.","Hormonale Verhütung ist unsicher – nicht-hormonale Methode verwenden.","Bei Augenschmerzen, Augenrötung oder Sehstörungen sofort ärztlich abklären lassen (Uveitis).","Alle Medikamente angeben, insbesondere HIV-Medikamente: Dosisanpassungen sind häufig nötig."],"darreichung":["Kapseln"]},"rifampicin":{"wirkmechanismus":"Hemmt die Vermehrung von Bakterien, indem es deren Ablesen der Erbinformation blockiert. Rifampicin bindet an die β-Untereinheit der bakteriellen DNA-abhängigen RNA-Polymerase und verhindert den Start der RNA-Synthese; es wirkt bakterizid, auch gegen ruhende und in Zellen liegende Tuberkulosebakterien. Weil sich bei Monotherapie rasch Resistenzen bilden, wird es fast immer kombiniert. Rifampicin aktiviert den Pregnan-X-Rezeptor und induziert dadurch stark CYP3A4, CYP2C9, CYP2C19, CYP1A2, UGT-Enzyme und P-Glykoprotein – mit sehr vielen Wechselwirkungen, die bis etwa 2 Wochen nach dem Absetzen anhalten.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Übelkeit, Erbrechen","Erhöhte Leberwerte und erhöhtes Bilirubin","Thrombozytopenie (Blutplättchenmangel), vor allem bei unregelmässiger Einnahme"],"gelegentlich":["Leukopenie (Mangel an weissen Blutkörperchen)","Durchfall"],"unbekannt":["Rotorange Verfärbung von Urin, Schweiss, Speichel, Tränen und Sputum (harmlos)","Grippeähnliche Reaktionen mit Fieber und Schüttelfrost, vor allem bei unregelmässiger Einnahme","Hepatitis (Leberentzündung), Gelbsucht","Appetitlosigkeit, Bauchbeschwerden, pseudomembranöse Kolitis","Hautausschlag, Juckreiz, Nesselsucht, Hautrötung","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS, AGEP)","Anaphylaxie, Schock, Atemnot","Agranulozytose, hämolytische Anämie, Eosinophilie, disseminierte intravasale Gerinnung","Akutes Nierenversagen, interstitielle Nephritis","Nebenniereninsuffizienz","Muskelschwäche, Menstruationsstörungen","Psychose","Porphyrie-Schub"]},"schwangerschaft":"Zur Behandlung einer Tuberkulose nach ärztlicher Abwägung möglich. In den letzten Wochen vor der Geburt kann es bei Mutter und Neugeborenem zu Blutungen kommen – Vitamin K wird empfohlen.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Stillen ist nach ärztlicher Abwägung in der Regel möglich, das Kind wird beobachtet.","hinweise":["Auf nüchternen Magen einnehmen: mindestens 30 Minuten bis 1 Stunde vor oder 2 Stunden nach einer Mahlzeit.","Urin, Schweiss und Tränen färben sich rotorange; weiche Kontaktlinsen können sich dauerhaft verfärben.","Regelmässig und ohne Unterbrechung einnehmen; Pausen und Wiederbeginn können schwere Überempfindlichkeitsreaktionen auslösen.","Alle anderen Medikamente angeben: Rifampicin schwächt sehr viele Arzneimittel ab, auch die Pille. Alkohol meiden."],"darreichung":["Kapseln"]},"rifampicin-isoniazid":{"wirkmechanismus":"Zwei Antibiotika, die Tuberkulosebakterien auf unterschiedliche Weise abtöten. Rifampicin hemmt die bakterielle DNA-abhängige RNA-Polymerase und damit die Bildung bakterieller Eiweisse. Isoniazid ist eine Vorstufe, die vom bakteriellen Enzym KatG aktiviert wird und dann die Synthese der Mykolsäuren blockiert – wesentlicher Bausteine der Zellwand von Mykobakterien. Die Kombination wirkt bakterizid und verhindert, dass sich resistente Erreger durchsetzen. Rifampicin ist zudem ein sehr starker Induktor von Leberenzymen (u. a. CYP3A4) und P-Glykoprotein.","nebenwirkungen":{"unbekannt":["Übelkeit, Erbrechen, Appetitlosigkeit, Bauchbeschwerden","Erhöhte Leberwerte, Hepatitis bis Leberversagen, Gelbsucht","Periphere Neuropathie (Kribbeln, Taubheit), Optikusneuritis, Krampfanfälle, Psychosen","Thrombozytopenie, Leukopenie, Agranulozytose, hämolytische Anämie","Grippeähnliches Syndrom, Atemnot, Schock, akutes Nierenversagen (vor allem bei unregelmässiger Einnahme)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS), Anaphylaxie","Lupus-ähnliches Syndrom, Clostridioides-difficile-Kolitis","Rot-orange Verfärbung von Urin, Schweiss, Speichel und Tränen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; eine Tuberkulose muss auch in der Schwangerschaft behandelt werden. Rifampicin in den letzten Wochen kann bei Mutter und Neugeborenem Blutungen begünstigen (Vitamin K), zusätzlich wird Vitamin B6 empfohlen.","stillzeit":"Beide Wirkstoffe gehen in die Muttermilch über; Stillen nach ärztlicher Abwägung möglich, Kind beobachten.","hinweise":["Auf nüchternen Magen einnehmen (mindestens 30 Minuten vor oder 2 Stunden nach einer Mahlzeit), regelmässig und ohne Unterbruch.","Urin, Schweiss und Tränen färben sich rot-orange; weiche Kontaktlinsen können dauerhaft verfärbt werden.","Hormonale Verhütung wirkt nicht zuverlässig – nicht-hormonal verhüten.","Auf Alkohol verzichten; bei Gelbsucht, dunklem Urin, starker Müdigkeit oder Übelkeit sofort ärztlich abklären."],"darreichung":["Überzogene Tabletten (Dragées)"]},"rifampicin-isoniazid-pyrazinamid":{"wirkmechanismus":"Drei Antibiotika, die Tuberkulosebakterien auf unterschiedliche Weise abtöten. Rifampicin hemmt die bakterielle RNA-Polymerase, Isoniazid blockiert nach Aktivierung durch das bakterielle Enzym KatG die Bildung der Mykolsäuren der Zellwand. Pyrazinamid wird in den Bakterien zu Pyrazinsäure umgewandelt und wirkt vor allem gegen langsam wachsende Erreger in saurer Umgebung, was die Gesamtbehandlung auf sechs Monate verkürzt. Rifampicin ist zudem ein sehr starker Induktor von Leberenzymen (u. a. CYP3A4) und P-Glykoprotein.","nebenwirkungen":{"unbekannt":["Übelkeit, Erbrechen, Appetitlosigkeit, Bauchbeschwerden","Erhöhte Leberwerte, Hepatitis bis Leberversagen, Gelbsucht","Hyperurikämie (erhöhte Harnsäure), Gichtanfall, Gelenkschmerzen","Periphere Neuropathie (Kribbeln, Taubheit), Optikusneuritis, Krampfanfälle, Psychosen","Thrombozytopenie, Leukopenie, Agranulozytose, hämolytische Anämie","Grippeähnliches Syndrom, Atemnot, Schock, akutes Nierenversagen (vor allem bei unregelmässiger Einnahme)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS), Anaphylaxie, Lichtempfindlichkeit","Rot-orange Verfärbung von Urin, Schweiss, Speichel und Tränen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; eine Tuberkulose muss auch in der Schwangerschaft behandelt werden. Rifampicin in den letzten Wochen kann bei Mutter und Neugeborenem Blutungen begünstigen (Vitamin K), zusätzlich wird Vitamin B6 empfohlen.","stillzeit":"Alle drei Wirkstoffe gehen in die Muttermilch über; Stillen nach ärztlicher Abwägung möglich, Kind beobachten.","hinweise":["Auf nüchternen Magen einnehmen (mindestens 30 Minuten vor oder 2 Stunden nach einer Mahlzeit), regelmässig und ohne Unterbruch.","Urin, Schweiss und Tränen färben sich rot-orange; weiche Kontaktlinsen können dauerhaft verfärbt werden. Hormonale Verhütung wirkt nicht zuverlässig.","Leberwerte und Harnsäure werden regelmässig kontrolliert; auf Alkohol verzichten, bei Gelbsucht oder dunklem Urin sofort ärztlich abklären.","Haut vor starker Sonne schützen."],"darreichung":["Überzogene Tabletten (Dragées)"]},"rifaximin":{"wirkmechanismus":"Vermindert im Darm die Bakterien, die Ammoniak und andere für das Gehirn schädliche Stoffe bilden. Rifaximin hemmt als Rifamycin-Abkömmling die bakterielle DNA-abhängige RNA-Polymerase und damit die Eiweissbildung der Bakterien. Weil weniger als 1 % aufgenommen wird, wirkt es fast ausschliesslich im Magen-Darm-Trakt.","nebenwirkungen":{"haeufig":["Schwindel","Kopfschmerzen","Übelkeit, Erbrechen","Oberbauchschmerzen, aufgeblähter Bauch","Durchfall","Muskelkrämpfe","Periphere Ödeme (Wassereinlagerungen in den Beinen)","Depression"],"gelegentlich":["Clostridioides-difficile-Infektion","Pilzinfektionen (Candida)","Anämie (Blutarmut)","Verwirrtheit"],"unbekannt":["Anaphylaxie und Angioödem (schwere allergische Reaktion, Schwellung von Haut und Schleimhäuten)","Thrombozytopenie (Mangel an Blutplättchen)","Veränderte INR-Werte","Hautausschlag, Juckreiz, Ekzem"]},"schwangerschaft":"Aus Vorsicht nicht empfohlen (begrenzte Daten; in Tierstudien Auswirkungen auf die Knochenentwicklung).","stillzeit":"Nicht bekannt, ob Rifaximin in die Muttermilch übergeht; Nutzen und Risiko ärztlich abwägen.","hinweise":["Unabhängig von den Mahlzeiten einnehmen; wird häufig zusammen mit Lactulose angewendet.","Der Urin kann sich rötlich verfärben – das ist harmlos.","Anhaltenden oder blutigen Durchfall ärztlich melden.","Schwindel kann die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"rilpivirin":{"wirkmechanismus":"Hemmt die Vermehrung von HIV. Rilpivirin ist ein NNRTI aus der Gruppe der Diarylpyrimidine, der nicht kompetitiv an eine Tasche nahe dem aktiven Zentrum der Reversen Transkriptase von HIV-1 bindet. Dadurch verändert sich die Form des Enzyms, und das Virus kann seine RNA nicht mehr in DNA umschreiben. Rilpivirin wird über CYP3A4 abgebaut; als Tablette braucht es Magensäure und eine Mahlzeit, um ausreichend aufgenommen zu werden.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Schwindel","Schlaflosigkeit","Übelkeit","Anstieg von Gesamt- und LDL-Cholesterin","Erhöhte Leberwerte (Transaminasen) und Pankreas-Amylase","Reaktionen an der Injektionsstelle (Schmerzen, Verhärtung, Knoten) bei der Depotspritze"],"haeufig":["Depression, depressive Verstimmung","Abnorme Träume, Schlafstörungen, Schläfrigkeit","Verminderter Appetit","Bauchschmerzen, Erbrechen, Mundtrockenheit","Hautausschlag","Müdigkeit","Fieber nach der Depotspritze","Veränderte Laborwerte (weniger weisse Blutkörperchen, Blutplättchen und Hämoglobin; Triglyceride, Lipase und Bilirubin erhöht)"],"gelegentlich":["Immunrekonstitutionssyndrom (Entzündungsreaktion zu Therapiebeginn)"],"selten":["Reaktion kurz nach der Depotspritze (Atemnot, Bauchkrämpfe, Schwitzen, Taubheitsgefühl im Mund)"],"unbekannt":["Schwere Haut- und Überempfindlichkeitsreaktionen mit Fieber und Organbeteiligung (DRESS)"]},"schwangerschaft":"Rilpivirin-Tabletten können bei Bedarf in der Schwangerschaft angewendet werden; wegen tieferer Spiegel im 2. und 3. Drittel Viruslast engmaschig kontrollieren. Die Depotspritze nur nach sorgfältiger Nutzen-Risiko-Abwägung.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Tabletten immer mit einer Mahlzeit einnehmen; ein Eiweissdrink allein genügt nicht.","Keine Säureblocker vom Typ PPI (z. B. Pantoprazol, Omeprazol); H2-Blocker und Antazida nur zeitversetzt.","Depotspritze: Termine genau einhalten; nach dem Absetzen bleibt Rilpivirin noch monatelang bis jahrelang im Körper – Anschlussbehandlung mit der Fachperson planen.","Bei Stimmungsveränderungen oder Hautausschlag mit Fieber sofort ärztlich melden."],"darreichung":["Filmtabletten","Depot-Injektionssuspension (intramuskulär)"]},"rimegepant":{"wirkmechanismus":"Blockiert den Andockplatz eines Botenstoffs, der bei Migräne Gefässerweiterung und Schmerz auslöst. Rimegepant ist ein kleines Molekül, das den CGRP-Rezeptor besetzt und so die CGRP-vermittelte Gefässerweiterung und neurogene Entzündung im Trigeminussystem hemmt. Anders als Triptane verengt es die Blutgefässe nicht. Es wird vor allem über CYP3A4 (in geringerem Mass CYP2C9) abgebaut und ist ein Substrat von P-Glykoprotein; die Halbwertszeit beträgt etwa 11 Stunden.","nebenwirkungen":{"haeufig":["Übelkeit"],"gelegentlich":["Überempfindlichkeitsreaktionen wie Atemnot oder schwerer Hautausschlag (auch Tage nach der Einnahme)"]},"schwangerschaft":"Vorsichtshalber vermeiden; keine ausreichenden Daten.","stillzeit":"Geht nur in sehr geringen Mengen (unter 1 % der mütterlichen Dosis) in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Schmelztablette auf oder unter die Zunge legen; sie löst sich ohne Wasser auf.","Höchstens 75 mg (1 Schmelztablette) pro Tag.","Zur Vorbeugung wird jeden zweiten Tag eine Schmelztablette eingenommen.","Bei neuen Medikamenten (v. a. Antibiotika, Pilzmittel, HIV-Mittel, Antiepileptika) Wechselwirkungen in der Apotheke prüfen lassen."],"darreichung":["Schmelztabletten (Lyophilisat zum Einnehmen)"]},"riociguat":{"wirkmechanismus":"Erweitert die Lungengefässe und senkt so den Druck im Lungenkreislauf. Riociguat stimuliert die lösliche Guanylatcyclase (sGC) auf zwei Wegen: direkt, unabhängig von Stickstoffmonoxid (NO), und indem es das Enzym für körpereigenes NO empfindlicher macht. Der Anstieg des Botenstoffs cGMP entspannt die glatte Gefässmuskulatur und wirkt Gefässumbau und Entzündung entgegen.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Schwindel","Dyspepsie (Verdauungsbeschwerden)","Übelkeit, Durchfall, Erbrechen","Periphere Ödeme (Wassereinlagerungen)"],"haeufig":["Gastroenteritis (Magen-Darm-Entzündung), Gastritis, Sodbrennen","Anämie (Blutarmut)","Herzklopfen","Hypotonie (tiefer Blutdruck)","Bluthusten, Nasenbluten","Verstopfte Nase","Bauchschmerzen, Verstopfung, Blähbauch, Schluckbeschwerden"],"gelegentlich":["Lungenblutung (schwer, teils tödlich)"]},"schwangerschaft":"Kontraindiziert – im Tierversuch fruchtschädigend. Frauen im gebärfähigen Alter müssen zuverlässig verhüten; monatliche Schwangerschaftstests werden empfohlen.","stillzeit":"Nicht stillen.","hinweise":["Nie zusammen mit Potenzmitteln (PDE-5-Hemmern), Nitraten oder «Poppers» einnehmen – lebensgefährlicher Blutdruckabfall.","Rauchen schwächt die Wirkung ab; einen Rauchstopp der Ärztin oder dem Arzt mitteilen (Dosisanpassung).","Antazida mindestens 2 Stunden vor oder 1 Stunde nach Riociguat einnehmen.","Schwindel kann die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"ripretinib":{"wirkmechanismus":"Blockiert dauerhaft eingeschaltete Wachstumssignale in GIST-Zellen. Ripretinib hemmt die Tyrosinkinasen KIT und PDGFRA über einen dualen Mechanismus: Es bindet sowohl an die «Schalttasche» (Switch Pocket) als auch an die Aktivierungsschleife und hält die Kinase so im inaktiven Zustand. Dadurch wirkt es gegen ein breites Spektrum von Resistenzmutationen, die nach Imatinib und anderen Kinasehemmern auftreten.","nebenwirkungen":{"sehrHaeufig":["Haarausfall","Hand-Fuss-Syndrom, trockene Haut, Hyperkeratose (Hornhautverdickung), gutartige Hautwucherungen","Muskelschmerzen, Muskelkrämpfe, Gelenkschmerzen","Übelkeit, Erbrechen, Verstopfung, Durchfall, Bauchschmerzen","Müdigkeit, Appetitverlust, Gewichtsabnahme","Bluthochdruck","Kopfschmerzen","Erhöhte Lipase, erhöhtes Bilirubin"],"haeufig":["Plattenepithelkarzinom der Haut, Keratoakanthom","Herzinsuffizienz, Abnahme der Herzpumpfunktion","Hypothyreose (Schilddrüsenunterfunktion)","Depression","Periphere Neuropathie (Kribbeln, Taubheit)","Tiefes Phosphat im Blut"],"gelegentlich":["Melanom (schwarzer Hautkrebs)"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nur bei zwingender Notwendigkeit. Frauen und Männer müssen während der Behandlung und mindestens 1 Woche danach zuverlässig verhüten.","stillzeit":"Während der Behandlung und mindestens 1 Woche danach nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit, mit oder ohne Mahlzeit; Tabletten unzerkaut schlucken.","Haut regelmässig selbst und ärztlich kontrollieren lassen; neue oder veränderte Hautstellen melden.","Blutdruck regelmässig messen.","Kein Johanniskraut; vor Operationen nach ärztlicher Anweisung pausieren."],"darreichung":["Tabletten"]},"risankizumab":{"wirkmechanismus":"Dämpft fehlgeleitete Entzündungsreaktionen in Haut, Gelenken und Darm. Risankizumab ist ein humanisierter monoklonaler IgG1-Antikörper, der selektiv die p19-Untereinheit von Interleukin-23 bindet und dessen Andocken an den Rezeptor verhindert. Dadurch werden die Aktivierung von Th17-Zellen und die Freisetzung entzündungsfördernder Botenstoffe gehemmt.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege"],"haeufig":["Pilzinfektionen der Haut (Tinea)","Kopfschmerzen","Juckreiz, Ausschlag","Müdigkeit","Reaktionen an der Einstichstelle"],"gelegentlich":["Follikulitis (Haarbalgentzündung)","Nesselsucht"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Medikamentenbedingte Leberschädigung (v. a. unter hoher Einleitungsdosis bei Morbus Crohn)"]},"schwangerschaft":"Vorsichtshalber während der Schwangerschaft vermeiden; Frauen im gebärfähigen Alter verhüten während und bis 21 Wochen nach der Behandlung.","stillzeit":"Übergang in die Muttermilch ist unbekannt; Entscheid über Stillen oder Therapie ärztlich abwägen.","hinweise":["Vor Beginn auf Tuberkulose testen und den Impfstatus vervollständigen lassen.","Bei Gelbsucht, dunklem Urin oder Oberbauchschmerzen sofort ärztlich abklären lassen.","Im Kühlschrank lagern, nicht schütteln."],"darreichung":["Injektionslösung (Fertigspritze, Fertigpen, Patrone mit Injektor zum Aufkleben)","Konzentrat zur Herstellung einer Infusionslösung"]},"risdiplam":{"wirkmechanismus":"Sorgt dafür, dass der Körper mehr vollständiges SMN-Eiweiss bildet, das die Nervenzellen der Muskulatur brauchen. Risdiplam verändert das Spleissen der SMN2-Prä-mRNA so, dass Exon 7 häufiger eingebaut wird. Dadurch entsteht mehr funktionsfähiges SMN-Protein. Als kleines Molekül gelangt es nach dem Schlucken in den ganzen Körper einschliesslich Gehirn und Rückenmark.","nebenwirkungen":{"sehrHaeufig":["Fieber","Durchfall","Hautausschlag","Kopfschmerzen"],"haeufig":["Übelkeit","Mundgeschwüre und Aphthen","Gelenkschmerzen","Harnwegsinfekt"],"unbekannt":["Hautvaskulitis (Entzündung kleiner Hautgefässe)"]},"schwangerschaft":"Nicht anwenden: im Tierversuch fruchtschädigend. Frauen im gebärfähigen Alter müssen während und bis 1 Monat nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einmal täglich nach einer Mahlzeit etwa zur gleichen Zeit mit der mitgelieferten Applikationsspritze einnehmen; danach etwas Wasser trinken.","Die zubereitete Lösung im Kühlschrank aufbewahren; Haut- und Augenkontakt mit Pulver oder Lösung vermeiden und sofort mit Wasser abspülen.","Wirksam verhüten: Frauen bis 1 Monat, Männer bis 4 Monate nach Ende der Behandlung."],"darreichung":["Pulver zur Herstellung einer Lösung zum Einnehmen"]},"risedronsaeure":{"wirkmechanismus":"Bremst den Knochenabbau, sodass die Knochendichte zunimmt und das Bruchrisiko sinkt. Risedronsäure ist ein stickstoffhaltiges Bisphosphonat, das sich an das Knochenmineral anlagert und von den knochenabbauenden Zellen (Osteoklasten) aufgenommen wird. Dort hemmt es die Farnesylpyrophosphat-Synthase und unterdrückt so deren Aktivität.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Verstopfung, Verdauungsbeschwerden, Übelkeit, Bauchschmerzen, Durchfall","Muskel-, Knochen- und Gelenkschmerzen"],"gelegentlich":["Iritis (Entzündung der Regenbogenhaut)","Gastritis, Entzündung der Speiseröhre oder des Zwölffingerdarms, Schluckbeschwerden","Speiseröhrengeschwür"],"selten":["Zungenentzündung, Verengung der Speiseröhre","Veränderte Leberwerte","Atypische Oberschenkelbrüche"],"sehrSelten":["Osteonekrose des äusseren Gehörgangs"],"unbekannt":["Kiefernekrose (Absterben von Kieferknochen)","Überempfindlichkeitsreaktionen, Angioödem, Anaphylaxie","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse), Vaskulitis","Uveitis (Augenentzündung)","Haarausfall","Schwere Leberstörungen"]},"schwangerschaft":"Kontraindiziert.","stillzeit":"Kontraindiziert.","hinweise":["Mindestens 30 Minuten vor der ersten Mahlzeit, dem ersten Getränk (ausser Leitungswasser) und anderen Arzneimitteln des Tages mit einem vollen Glas Leitungswasser unzerkaut einnehmen.","Nach der Einnahme mindestens 30 Minuten aufrecht bleiben; nicht vor dem Schlafengehen einnehmen.","Für ausreichend Calcium und Vitamin D sorgen, diese aber zeitversetzt einnehmen.","Vor Beginn Zahnstatus kontrollieren; neue Oberschenkel- oder Leistenschmerzen melden."],"darreichung":["Filmtabletten"]},"risperidon":{"wirkmechanismus":"Dämpft Wahn, Halluzinationen, Erregung und Aggression, indem es die Wirkung von Dopamin und Serotonin im Gehirn hemmt. Risperidon blockiert stark Serotonin-5-HT2A- und Dopamin-D2-Rezeptoren, ausserdem Alpha-1- und Histamin-H1-Rezeptoren (Blutdruckabfall, Müdigkeit). Es wird über CYP2D6 zum ebenso wirksamen 9-Hydroxy-Risperidon (Paliperidon) umgewandelt; beide zusammen bilden die aktive Fraktion.","nebenwirkungen":{"sehrHaeufig":["Parkinsonismus (Muskelsteife, Bewegungsarmut, Zittern)","Schläfrigkeit, Sedierung","Kopfschmerzen","Schlaflosigkeit"],"haeufig":["Erhöhtes Prolaktin (Milchfluss, Zyklusstörungen, Brustvergrösserung)","Gewichtszunahme, Appetitveränderungen","Sitzunruhe (Akathisie), Dystonie, Schwindel, Dyskinesien","Angst, Unruhe, Depression","Herzrasen, Bluthochdruck","Atemwegsinfekte, Lungenentzündung, Husten, Nasenbluten","Übelkeit, Erbrechen, Verstopfung, Durchfall, Bauchschmerzen","Ödeme, Fieber, Muskel- und Gelenkschmerzen"],"gelegentlich":["Diabetes, erhöhter Blutzucker","Spätdyskinesien, Krampfanfälle","Ohnmacht, orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","QT-Verlängerung, AV-Block, Vorhofflimmern, Bradykardie","Neutropenie, Anämie","Sexuelle Funktionsstörungen, Erektionsstörung","Schluckstörungen, Aspirationspneumonie","Durchblutungsstörungen des Gehirns (bei älteren Menschen mit Demenz)"],"selten":["Malignes neuroleptisches Syndrom","Venöse Thromboembolie","Schlafapnoe","Pankreatitis, Darmverschluss","Gelbsucht","Priapismus","SIADH (Natriummangel durch zu viel antidiuretisches Hormon)","Floppy-Iris-Syndrom bei Operation des Grauen Stars"],"sehrSelten":["Diabetische Ketoazidose"],"unbekannt":["Agranulozytose","Anaphylaxie, Angioödem","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Entzugssymptome und Bewegungsstörungen beim Neugeborenen"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn der Nutzen das Risiko überwiegt. Nach Einnahme im letzten Drittel sind beim Neugeborenen Bewegungsstörungen und Entzugssymptome möglich.","stillzeit":"Risperidon und sein Wirkmetabolit gehen in die Muttermilch über. Nur nach ärztlicher Abwägung stillen.","hinweise":["Gewicht, Blutzucker und Blutfette regelmässig kontrollieren.","Vor einer Operation am Grauen Star die Augenärztin bzw. den Augenarzt über die Einnahme informieren.","Langsam aufstehen (Schwindel, Blutdruckabfall); Alkohol meiden, Fahrtüchtigkeit kann beeinträchtigt sein.","Risperdal Consta wird alle 2 Wochen gespritzt; in den ersten 3 Wochen sind zusätzlich Tabletten nötig."],"darreichung":["Filmtabletten","Schmelztabletten","Lösung zum Einnehmen","Depot-Injektionssuspension"]},"ritlecitinib":{"wirkmechanismus":"Bremst die Immunzellen, die bei Alopecia areata die Haarwurzeln angreifen. Ritlecitinib hemmt irreversibel die Januskinase 3 (JAK3) sowie Kinasen der TEC-Familie, indem es fest an einen Cysteinrest bindet, den JAK1, JAK2 und TYK2 nicht besitzen. Dadurch werden die Signalwege von Zytokinen wie Interleukin-15 sowie die Aktivität zytotoxischer T- und NK-Zellen gedämpft, die den Haarfollikel schädigen.","nebenwirkungen":{"haeufig":["Durchfall","Akne","Infektionen der oberen Atemwege","Nesselsucht, Hautausschlag","Haarbalgentzündung (Follikulitis)","Schwindel","Gürtelrose (Herpes zoster)","Erhöhte CK (Muskelenzym)"],"gelegentlich":["Verminderung von Blutplättchen und Lymphozyten","Erhöhte Leberwerte (ALT, AST)"],"unbekannt":["Thrombosen und Lungenembolie","Bösartige Erkrankungen, inkl. heller Hautkrebs","Schwere und opportunistische Infektionen"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während und bis 1 Monat nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten einnehmen; Kapseln ganz schlucken.","Blutbild nach 4 Wochen und danach regelmässig; Leberwerte und Haut kontrollieren lassen.","Bei plötzlicher Atemnot, Brustschmerzen oder einem geschwollenen, schmerzhaften Bein sofort ärztliche Hilfe holen.","Keine Lebendimpfungen; Impfungen möglichst vor Beginn nachholen."],"darreichung":["Hartkapseln"]},"ritonavir":{"wirkmechanismus":"Hemmt das HIV-Enzym Protease und verstärkt vor allem die Wirkung anderer HIV-Medikamente. Ritonavir blockiert die HIV-1-Protease, sodass das Virus seine Vorläufer-Eiweisse nicht spalten kann und unreife, nicht ansteckende Viruspartikel entstehen. Schon in niedriger Dosis hemmt es stark und irreversibel das Abbauenzym CYP3A4 sowie P-Glykoprotein in Darm und Leber; dadurch steigen die Spiegel gleichzeitig gegebener Proteasehemmer. Gleichzeitig induziert Ritonavir andere Enzyme (z. B. CYP1A2, CYP2B6, CYP2C9, CYP2C19 und die Glucuronidierung) und kann so die Spiegel anderer Medikamente senken.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Geschmacksstörungen, Kribbeln um den Mund und in Händen und Füssen","Kopfschmerzen, Schwindel, periphere Neuropathie","Hautausschlag, Juckreiz","Müdigkeit, Schwäche","Hitzegefühl (Flush)","Rachenschmerzen, Husten"],"haeufig":["Erhöhte Blutfette (Cholesterin, Triglyceride), Gicht","Erhöhter Blutzucker, Diabetes","Hepatitis, erhöhte Leberwerte","Pankreatitis (Bauchspeicheldrüsenentzündung)","Blutbildveränderungen (Leukopenie, Neutropenie, Thrombozytopenie)","Schlaflosigkeit, Angst, Verwirrtheit, Krampfanfälle","Muskelschmerzen, erhöhte CK-Werte","Ohnmacht, Blutdruckabfall oder -anstieg"],"gelegentlich":["Herzinfarkt","Nierenversagen"],"selten":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Anaphylaxie"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit angewendet werden; umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Menschen mit HIV wird generell vom Stillen abgeraten; allenfalls nach eingehender Beratung durch die HIV-Fachperson.","hinweise":["Mit einer Mahlzeit einnehmen; Tabletten ganz schlucken.","Vor jeder neuen Behandlung – auch mit rezeptfreien oder pflanzlichen Mitteln wie Johanniskraut – Ärztin, Arzt oder Apotheke informieren: sehr viele Wechselwirkungen.","Die Nebenwirkungen sind bei der heute üblichen niedrigen Booster-Dosis deutlich seltener als bei der früheren vollen Dosis.","Blutfette, Blutzucker und Leberwerte werden regelmässig kontrolliert."],"darreichung":["Filmtabletten"]},"rituximab":{"wirkmechanismus":"Entfernt gezielt B-Lymphozyten (eine Art weisser Blutkörperchen) aus Blut und Gewebe. Rituximab ist ein chimärer (Maus/Mensch) monoklonaler Antikörper gegen das Oberflächenmolekül CD20, das auf normalen und bösartigen B-Zellen vorkommt. Die markierten Zellen werden durch das Komplementsystem, durch Immunzellen (antikörperabhängige zelluläre Zytotoxizität) und durch Auslösen des programmierten Zelltods zerstört. Die B-Zellen erholen sich meist erst 6–12 Monate nach der letzten Gabe.","nebenwirkungen":{"sehrHaeufig":["Infusionsreaktionen (Fieber, Schüttelfrost, Hautrötung, Blutdruckabfall, Atembeschwerden), v. a. bei der ersten Infusion","Bakterielle und virale Infektionen, Bronchitis","Neutropenie, Leukopenie","Übelkeit","Juckreiz, Hautausschlag, Haarausfall","Schwäche, Kopfschmerzen","Erniedrigte Antikörperspiegel (IgG)"],"haeufig":["Sepsis, Lungenentzündung, Gürtelrose (Herpes zoster), Pilzinfektionen","Anämie, Thrombozytopenie, febrile Neutropenie","Herzrhythmusstörungen, Herzrasen, Herzinfarkt","Blutdruckanstieg oder -abfall","Bronchospasmus, Atemnot, Husten","Erbrechen, Durchfall, Bauchschmerzen, Stomatitis","Muskel-, Gelenk- und Rückenschmerzen","Kribbeln, Schwindel, Angst, Schlaflosigkeit"],"gelegentlich":["Herzschwäche, Angina pectoris","Hämolytische oder aplastische Anämie, Gerinnungsstörungen","Asthma, Sauerstoffmangel"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Interstitielle Lungenerkrankung","Pneumocystis-Pneumonie, schwere Virusinfektionen"],"sehrSelten":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Tumorlyse-Syndrom","Nierenversagen","Magen-Darm-Perforation"],"unbekannt":["Hepatitis-B-Reaktivierung bis zum Leberversagen","Spät auftretende Neutropenie (Wochen nach der letzten Gabe)","Enterovirale Meningoenzephalitis (Hirn- und Hirnhautentzündung)"]},"schwangerschaft":"Nur bei zwingender Indikation (kann beim Kind die B-Zellen vermindern). Frauen müssen während und bis 12 Monate nach der Behandlung sicher verhüten.","stillzeit":"Rituximab geht nur in sehr geringen Mengen in die Muttermilch über; Stillen wird während der Behandlung und einige Monate danach dennoch nicht empfohlen.","hinweise":["Vor jeder Infusion erhalten Sie Medikamente gegen Fieber und Allergie (z. B. Paracetamol, Antihistaminikum, oft Kortison).","Vor Beginn wird auf Hepatitis B getestet; ausstehende Impfungen möglichst vorher durchführen.","Blutdrucksenkende Medikamente werden eventuell 12 Stunden vor der Infusion pausiert – nur nach ärztlicher Anweisung.","Fieber, Infektzeichen, Verwirrtheit, Seh- oder Gangstörungen sofort melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Injektionslösung zur subkutanen Anwendung"]},"rivaroxaban":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es einen zentralen Gerinnungsfaktor direkt blockiert. Rivaroxaban bindet direkt und reversibel an den Gerinnungsfaktor Xa, sowohl frei im Blut als auch im Gerinnsel, ohne Antithrombin zu benötigen. Dadurch entsteht weniger Thrombin und es bilden sich keine neuen Gerinnsel. Es wird über CYP3A4 und den Transporter P-Glykoprotein abgebaut und etwa zu einem Drittel unverändert über die Nieren ausgeschieden; als Gegenmittel steht Andexanet alfa zur Verfügung.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Schwindel, Kopfschmerzen","Blutungen: Nasen-, Zahnfleisch-, Augen-, Magen-Darm- und Harnwegsblutungen, Blutergüsse","Verstärkte Monatsblutung (bei Frauen unter 55 Jahren sehr häufig)","Bauchschmerzen, Verdauungsbeschwerden, Übelkeit, Verstopfung, Durchfall, Erbrechen","Erhöhte Leberwerte (Transaminasen)","Juckreiz, Hautausschlag","Tiefer Blutdruck, Fieber, Wassereinlagerungen, Kraftlosigkeit, eingeschränkte Nierenfunktion"],"gelegentlich":["Hirnblutung","Thrombozytopenie oder Thrombozytose (veränderte Plättchenzahl)","Allergische Reaktionen, Angioödem, Nesselsucht","Ohnmacht, schneller Herzschlag","Mundtrockenheit","Leberfunktionsstörung, erhöhtes Bilirubin","Gelenkblutungen"],"selten":["Gelbsucht, Gallestauung, Hepatitis","Muskelblutungen","Pseudoaneurysma nach Gefässpunktion"],"sehrSelten":["Anaphylaktische Reaktionen bis Schock","Schwere Haut- und Überempfindlichkeitsreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Eosinophile Pneumonie"],"unbekannt":["Kompartmentsyndrom oder akutes Nierenversagen als Folge einer Blutung","Antikoagulanzien-assoziierte Nephropathie (Nierenschädigung durch Blutungen in der Niere)"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter sollen während der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – entweder abstillen oder die Behandlung absetzen.","hinweise":["Tabletten zu 15 mg und 20 mg mit einer Mahlzeit einnehmen (sonst ungenügende Aufnahme); 2.5 mg und 10 mg unabhängig vom Essen.","Tabletten dürfen zerstossen und mit Wasser oder Apfelmus eingenommen werden.","Nicht eigenmächtig absetzen – Gefahr von Schlaganfall oder Thrombose; vor Operationen, Zahnbehandlungen und neuen Medikamenten Arzt oder Apotheke informieren.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, starke Kopfschmerzen, ungewöhnliche Blutergüsse) sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"rivastigmin":{"wirkmechanismus":"Verbessert bei Demenz vorübergehend Gedächtnis und Alltagsfähigkeiten, indem es den Abbau des Botenstoffs Acetylcholin im Gehirn bremst. Rivastigmin hemmt pseudoirreversibel sowohl die Acetylcholinesterase als auch die Butyrylcholinesterase. Es wird nicht über CYP-Enzyme der Leber, sondern durch die Cholinesterasen selbst abgebaut und hat daher wenige pharmakokinetische Wechselwirkungen. Das Pflaster gibt den Wirkstoff gleichmässig ab und verursacht weniger Magen-Darm-Beschwerden.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen","Durchfall","Appetitlosigkeit","Schwindel"],"haeufig":["Unruhe, Verwirrtheit, Angst, Albträume","Kopfschmerzen, Schläfrigkeit, Zittern (Tremor)","Bauchschmerzen, Dyspepsie (Verdauungsbeschwerden)","Vermehrtes Schwitzen","Müdigkeit, Schwäche, Gewichtsabnahme","Hautreaktionen an der Pflasterstelle (Rötung, Juckreiz)"],"gelegentlich":["Schlaflosigkeit, Depression","Ohnmacht (Synkope), Stürze","Erhöhte Leberwerte"],"selten":["Krampfanfälle","Angina pectoris (Brustenge)","Magen- und Zwölffingerdarmgeschwüre","Hautausschlag"],"sehrSelten":["Herzrhythmusstörungen (Bradykardie, AV-Block, Vorhofflimmern)","Verschlechterung einer Parkinson-Krankheit, extrapyramidale Symptome","Halluzinationen","Magen-Darm-Blutungen, Pankreatitis","Schweres Erbrechen mit Speiseröhrenriss"],"unbekannt":["Sick-Sinus-Syndrom","Aggressivität","Hepatitis","Pisa-Syndrom (seitliche Rumpfneigung)","Dehydratation (Flüssigkeitsmangel) bei anhaltendem Erbrechen","Allergische Kontaktdermatitis, auch ausgebreitet (Pflaster)"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Nicht stillen.","hinweise":["Kapseln und Lösung zweimal täglich zum Frühstück und Abendessen einnehmen.","Nach einem Unterbruch von mehr als 3 Tagen nur mit der niedrigsten Dosis neu beginnen (sonst starkes Erbrechen möglich).","Pflaster: täglich nur ein Pflaster, das alte zuvor entfernen und die Klebestelle wechseln – mehrere Pflaster gleichzeitig können zu gefährlicher Überdosierung führen.","Bei anhaltendem Erbrechen, Durchfall oder Gewichtsverlust ärztlich abklären lassen."],"darreichung":["Kapseln","Lösung zum Einnehmen","Transdermales Pflaster"]},"rizatriptan":{"wirkmechanismus":"Lindert den Migränekopfschmerz, indem es erweiterte Blutgefässe im Kopf verengt und die Ausschüttung entzündlicher Botenstoffe hemmt. Rizatriptan ist ein selektiver Agonist an Serotonin-5-HT1B- und -5-HT1D-Rezeptoren an Hirngefässen und Trigeminusnerven und hemmt die Freisetzung von Neuropeptiden wie CGRP. Der Abbau erfolgt hauptsächlich über die Monoaminoxidase A (MAO-A).","nebenwirkungen":{"haeufig":["Schwindel, Schläfrigkeit, Kopfschmerzen","Kribbeln, Empfindungsstörungen, Konzentrationsstörungen","Herzklopfen, Herzrasen","Hitzewallungen, Gesichtsrötung","Übelkeit, Erbrechen, Mundtrockenheit, Durchfall, Verdauungsbeschwerden","Schweregefühl, Schmerzen oder Engegefühl in Brust, Hals oder Nacken","Müdigkeit, Schwächegefühl"],"gelegentlich":["Gang- und Koordinationsstörungen (Ataxie), Drehschwindel","Verschwommenes Sehen","Verwirrtheit, Nervosität, Schlaflosigkeit","Herzrhythmusstörungen, Blutdruckanstieg","Juckreiz, Nesselsucht, Angioödem (Schwellung von Gesicht, Zunge, Rachen), Hautausschlag, Schwitzen","Muskelschmerzen, Muskelkrämpfe","Geschmacksstörungen"],"selten":["Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)","Ohnmacht (Synkope)","Pfeifende Atmung"],"unbekannt":["Krampfanfälle","Serotoninsyndrom","Durchblutungsstörung des Herzens, Herzinfarkt","Schlaganfall","Durchblutungsstörungen der Beine oder des Darms (ischämische Kolitis)","Schwere Hautreaktionen (toxische epidermale Nekrolyse)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur nach strenger ärztlicher Abwägung anwenden.","stillzeit":"Übertritt in die Muttermilch beim Menschen nicht bekannt (im Tierversuch ja); nach der Einnahme 24 Stunden nicht stillen.","hinweise":["Bei Einnahme von Propranolol die Dosis mit der Ärztin oder dem Arzt absprechen.","Schmelztabletten auf der Zunge zergehen lassen; sie wirken nicht schneller als normale Tabletten.","Akutmittel gegen Migräne an höchstens 10 Tagen pro Monat verwenden, sonst droht Kopfschmerz durch Medikamentenübergebrauch.","Kann Schläfrigkeit und Schwindel verursachen – Vorsicht beim Autofahren."],"darreichung":["Tabletten","Schmelztabletten (Lingualtabletten)"]},"rocuronium":{"wirkmechanismus":"Entspannt die Skelettmuskulatur vollständig, sodass Intubation und Operation möglich werden; die Atmung muss deshalb maschinell unterstützt werden. Rocuronium blockiert kompetitiv die nikotinischen Acetylcholinrezeptoren an der motorischen Endplatte und verhindert so die Übertragung des Nervenimpulses auf den Muskel. Die Wirkung setzt innerhalb von 1–2 Minuten ein und kann mit Sugammadex (bindet Rocuronium direkt) oder mit Neostigmin aufgehoben werden. Rocuronium wirkt weder schmerzstillend noch schlaffördernd.","nebenwirkungen":{"gelegentlich":["Tachykardie (Herzrasen), Blutdruckabfall","Schmerzen oder Reaktion an der Injektionsstelle","Verlängerte Muskelerschlaffung, verzögertes Erwachen aus der Narkose","Verminderte oder verstärkte Wirkung"],"sehrSelten":["Anaphylaxie und anaphylaktischer Schock (schwere allergische Reaktion)","Bronchospasmus (Verkrampfung der Atemwege)","Angioödem, Nesselsucht, Hautrötung, Hitzegefühl","Muskelschwäche, Myopathie nach Langzeitanwendung zusammen mit Kortison","Kreislaufkollaps"],"unbekannt":["Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; beim Kaiserschnitt kann Rocuronium eingesetzt werden, ohne dass Nachteile für das Neugeborene beobachtet wurden.","stillzeit":"Nur nach Abwägung; nach einer Einzeldosis wird empfohlen, etwa 6 Stunden mit dem Stillen zu warten.","hinweise":["Wird nur von Fachpersonal für Anästhesie oder Intensivmedizin mit Beatmungsmöglichkeit verabreicht.","Bekannte Allergien gegen Narkose- oder Muskelentspannungsmittel vor der Operation unbedingt angeben.","Nach einer Narkose 24 Stunden nicht Auto fahren und keine Maschinen bedienen."],"darreichung":["Injektionslösung"]},"roflumilast":{"wirkmechanismus":"Hemmt die Entzündung in der Lunge, erweitert die Bronchien aber nicht direkt. Roflumilast und sein ebenfalls wirksamer Hauptmetabolit Roflumilast-N-Oxid hemmen selektiv die Phosphodiesterase 4 (PDE4), das wichtigste cAMP-abbauende Enzym in Entzündungszellen. Der Anstieg von cAMP dämpft die Aktivität von Neutrophilen, Makrophagen und anderen Entzündungszellen und vermindert so die Häufigkeit von COPD-Exazerbationen. Der Abbau erfolgt über CYP3A4 und CYP1A2.","nebenwirkungen":{"haeufig":["Gewichtsabnahme, verminderter Appetit","Schlaflosigkeit","Kopfschmerzen","Durchfall","Übelkeit","Bauchschmerzen"],"gelegentlich":["Überempfindlichkeitsreaktionen","Angst","Zittern (Tremor), Schwindel","Herzklopfen (Palpitationen)","Erbrechen, Gastritis, Reflux, Verdauungsbeschwerden","Hautausschlag","Muskelkrämpfe, Muskelschwäche, Muskel- und Rückenschmerzen","Müdigkeit, Schwäche, Unwohlsein"],"selten":["Suizidgedanken und suizidales Verhalten","Depression, Nervosität, Panikattacken","Angioödem, Nesselsucht","Gynäkomastie (Brustvergrösserung beim Mann)","Infekte der Atemwege (ohne Lungenentzündung)","Blut im Stuhl, Verstopfung","Erhöhte Leberwerte","Geschmacksstörung"]},"schwangerschaft":"Anwendung nicht empfohlen. Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","stillzeit":"Roflumilast geht im Tierversuch in die Milch über; in der Stillzeit nicht anwenden.","hinweise":["Einmal täglich zur gleichen Zeit mit Wasser einnehmen, unabhängig von den Mahlzeiten.","Durchfall, Übelkeit, Kopfschmerzen und Gewichtsabnahme treten vor allem in den ersten Wochen auf; das Gewicht regelmässig kontrollieren.","Bei Stimmungsveränderungen, anhaltender Schlaflosigkeit oder Suizidgedanken sofort ärztliche Hilfe suchen.","Wirkt nicht bei akuter Atemnot und ersetzt die inhalativen Bronchienerweiterer nicht."],"darreichung":["Filmtabletten"]},"romiplostim":{"wirkmechanismus":"Regt das Knochenmark an, mehr Blutplättchen zu bilden. Romiplostim ist ein gentechnisch hergestelltes Fusionsprotein («Peptibody»), das an den Thrombopoetin-Rezeptor (c-Mpl) der Megakaryozyten bindet und ihn wie das körpereigene Thrombopoetin aktiviert. Über den JAK2/STAT5-Signalweg werden Vermehrung und Reifung der Megakaryozyten gesteigert, sodass die Thrombozytenzahl ansteigt. Die Wirkung hält nur an, solange das Mittel regelmässig gegeben wird.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Überempfindlichkeitsreaktionen (z. B. Hautausschlag, Nesselsucht)","Infektionen der oberen Atemwege"],"haeufig":["Schwindel, Schlafstörungen, Missempfindungen (Kribbeln)","Gelenk-, Muskel-, Rücken- und Gliederschmerzen","Übelkeit, Durchfall, Bauchschmerzen, Verstopfung","Müdigkeit, grippeartige Beschwerden, Fieber, Wassereinlagerungen","Veränderungen im Knochenmark (vermehrte Retikulinfasern)","Erneuter Abfall der Blutplättchen nach dem Absetzen","Lungenembolie","Reaktionen an der Injektionsstelle"],"gelegentlich":["Thrombosen (z. B. tiefe Venenthrombose, Pfortaderthrombose)","Herzinfarkt","Erythromelalgie (brennende Rötung von Händen und Füssen)","Milzvergrösserung"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; im Tierversuch gelangte Romiplostim zum Ungeborenen. Während der Schwangerschaft nicht empfohlen; Frauen im gebärfähigen Alter sollen verhüten.","stillzeit":"Nicht bekannt, ob Romiplostim in die Muttermilch übergeht. Stillen oder Behandlung nur nach ärztlicher Abwägung.","hinweise":["Wird einmal wöchentlich unter die Haut gespritzt; die Dosis richtet sich nach der wöchentlich bestimmten Plättchenzahl.","Nicht eigenmächtig absetzen: nach dem Absetzen können die Plättchen rasch abfallen und Blutungen auftreten.","Ziel ist kein normaler, sondern ein sicherer Plättchenwert (meist über 50'000 pro Mikroliter)."],"darreichung":["Pulver zur Herstellung einer Injektionslösung (subkutan)"]},"romosozumab":{"wirkmechanismus":"Regt den Aufbau neuer Knochensubstanz an und bremst gleichzeitig den Knochenabbau. Romosozumab ist ein humanisierter monoklonaler IgG2-Antikörper gegen Sklerostin, einen körpereigenen Hemmstoff der Knochenbildung. Durch die Blockade wird der Wnt-Signalweg in den knochenbildenden Zellen (Osteoblasten) aktiviert, und der Abbau durch die Osteoklasten nimmt ab. Knochenmasse und -festigkeit von Wirbelsäule und Hüfte steigen innerhalb eines Jahres deutlich; danach wird mit einem knochenabbauhemmenden Mittel weiterbehandelt.","nebenwirkungen":{"sehrHaeufig":["Nasopharyngitis (Erkältung)","Gelenkschmerzen"],"haeufig":["Sinusitis (Nebenhöhlenentzündung)","Überempfindlichkeitsreaktionen, Hautausschlag, Dermatitis (Hautentzündung)","Kopfschmerzen","Nackenschmerzen, Muskelkrämpfe","Reaktionen an der Injektionsstelle"],"gelegentlich":["Herzinfarkt","Schlaganfall","Hypokalzämie (tiefes Calcium)","Nesselsucht","Katarakt (grauer Star)"],"selten":["Angioödem (Schwellung von Gesicht oder Rachen)","Erythema multiforme (schwere Hautreaktion)","Kiefernekrose (Absterben von Kieferknochen)","Atypische Oberschenkelbrüche"]},"schwangerschaft":"Nicht für Frauen im gebärfähigen Alter bestimmt; in der Schwangerschaft nicht anwenden.","stillzeit":"Nicht anwenden.","hinweise":["Bei Brustschmerzen, Atemnot, plötzlicher Lähmung, Sprech- oder Sehstörung sofort den Notruf 144 wählen (mögliche Zeichen von Herzinfarkt oder Schlaganfall).","Während der Behandlung genügend Calcium und Vitamin D zuführen; regelmässige Zahnkontrollen.","Nach Abschluss der 12 Monate wird die Behandlung mit einem knochenabbauhemmenden Mittel fortgesetzt, damit der Effekt erhalten bleibt."],"darreichung":["Injektionslösung in Fertigspritze bzw. Fertigpen (subkutan)"]},"ropeginterferon-alfa-2b":{"wirkmechanismus":"Bremst die krankhaft gesteigerte Bildung von Blutzellen im Knochenmark. Ropeginterferon alfa-2b ist Interferon alfa-2b mit einer an einer einzigen Stelle gebundenen Polyethylenglykol-Kette, die eine lange Wirkdauer ermöglicht. Es bindet an den Typ-I-Interferonrezeptor und aktiviert über den JAK-STAT-Signalweg Gene, die die Vermehrung blutbildender Stammzellen hemmen. Dabei wirkt es bevorzugt auf die krankhaften Zellen mit JAK2-V617F-Mutation, deren Anteil im Blut sinkt.","nebenwirkungen":{"sehrHaeufig":["Leukopenie (Mangel an weissen Blutkörperchen), Thrombozytopenie (Mangel an Blutplättchen)","Gelenk- und Muskelschmerzen","Müdigkeit","Grippeähnliche Beschwerden","Erhöhte Leberwerte (GGT)"],"haeufig":["Anämie (Blutarmut), Neutropenie","Schilddrüsenunter- oder -überfunktion","Depression, Schlafstörungen","Kopfschmerzen, Schwindel","Juckreiz, Haarausfall, Hautausschlag","Übelkeit, Durchfall, Bauchschmerzen","Fieber, Reaktionen an der Injektionsstelle","Erhöhte Leberwerte (ALT, AST)"],"unbekannt":["Suizidgedanken, Suizidversuch","Netzhautblutungen und andere Netzhautschäden","Herzrhythmusstörungen (z. B. Vorhofflimmern), Herzschwäche","Lungeninfiltrate, Pneumonitis (Lungenentzündung)","Autoimmunerkrankungen (z. B. Thyreoiditis, Sarkoidose)","Diabetes mellitus","Überempfindlichkeitsreaktionen bis Anaphylaxie","Zahn- und Zahnfleischerkrankungen"]},"schwangerschaft":"Nicht empfohlen. Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob der Wirkstoff in die Muttermilch übergeht; ein Risiko für das Kind ist nicht auszuschliessen – Stillen nur nach ärztlicher Abwägung.","hinweise":["Regelmässige Kontrollen von Blutbild, Leber-, Nieren- und Schilddrüsenwerten.","Augenärztliche Untersuchung vor Beginn; neue Sehstörungen sofort melden.","Bei Stimmungsveränderungen oder Suizidgedanken sofort ärztliche Hilfe holen.","Regelmässige zahnärztliche Kontrollen und gute Mundhygiene."],"darreichung":["Injektionslösung im Fertigpen (subkutan)"]},"ropinirol":{"wirkmechanismus":"Ahmt im Gehirn die Wirkung des Botenstoffs Dopamin nach, der bei Parkinson fehlt. Ropinirol ist ein nicht-ergoliner Agonist an den Dopamin-D2- und -D3-Rezeptoren im Striatum und bessert so Bewegungsarmut, Steifigkeit und Zittern. Beim Restless-Legs-Syndrom lindert es über die gleichen Rezeptoren Missempfindungen und Bewegungsdrang der Beine. Es wird in der Leber hauptsächlich über CYP1A2 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Schläfrigkeit (Somnolenz)","Dyskinesien (Überbewegungen, bei Kombination mit Levodopa)"],"haeufig":["Halluzinationen, Verwirrtheit","Schwindel, Ohnmacht (Synkope)","Erbrechen, Bauchschmerzen, Sodbrennen, Verstopfung","Beinödeme (Wassereinlagerungen)","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Müdigkeit, Nervosität"],"gelegentlich":["Plötzliches Einschlafen, übermässige Tagesschläfrigkeit","Psychotische Reaktionen (Wahn, Paranoia, Delir)"],"unbekannt":["Impulskontrollstörungen (Spielsucht, Kaufsucht, Essattacken, gesteigertes sexuelles Verlangen)","Dopamin-Dysregulationssyndrom, aggressives Verhalten","Überempfindlichkeitsreaktionen (Nesselsucht, Angioödem, Ausschlag)","Erhöhte Leberwerte","Dopaminagonisten-Entzugssyndrom (Apathie, Angst, Depression, Schmerzen beim Absetzen)","Augmentation beim Restless-Legs-Syndrom"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen; im Tierversuch schädliche Wirkungen. Nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Ropinirol kann die Milchbildung hemmen. In der Stillzeit nicht anwenden.","hinweise":["Mit einer Mahlzeit einnehmen – das vermindert Übelkeit. Retardtabletten ganz schlucken.","Bei Tagesschläfrigkeit oder plötzlichem Einschlafen nicht Auto fahren und keine Maschinen bedienen.","Nicht abrupt absetzen, sondern ärztlich angeleitet ausschleichen.","Angehörige sollten auf Spielsucht, Kaufsucht oder auffälliges Sexualverhalten achten."],"darreichung":["Filmtabletten","Retardtabletten"]},"ropivacain":{"wirkmechanismus":"Betäubt örtlich, indem es die Weiterleitung von Schmerzsignalen in den Nerven vorübergehend unterbricht. Ropivacain blockiert die spannungsabhängigen Natriumkanäle der Nervenmembran und verhindert so die Fortleitung von Aktionspotenzialen. Es ist als reines S-Enantiomer weniger herzschädigend als Bupivacain und blockiert in niedriger Dosis die Schmerzfasern stärker als die motorischen Nerven, sodass die Beweglichkeit oft erhalten bleibt. Der Abbau erfolgt in der Leber hauptsächlich über CYP1A2.","nebenwirkungen":{"sehrHaeufig":["Hypotonie (Blutdruckabfall)","Übelkeit"],"haeufig":["Kribbeln (Parästhesien), Schwindel, Kopfschmerzen","Bradykardie oder Tachykardie (langsamer oder schneller Puls)","Blutdruckanstieg","Erbrechen","Harnverhalt","Rückenschmerzen","Fieber, Schüttelfrost"],"gelegentlich":["Angst","Zeichen einer Vergiftung des Nervensystems: Taubheit um den Mund, Ohrgeräusche, Sehstörungen, Muskelzucken, Krampfanfälle","Synkope (Ohnmacht)","Atemnot","Unterkühlung"],"selten":["Herzrhythmusstörungen, Herzstillstand","Allergische Reaktionen bis zur Anaphylaxie, Angioödem"],"unbekannt":["Dyskinesie (unwillkürliche Bewegungen)"]},"schwangerschaft":"Wird zur Schmerzlinderung unter der Geburt und beim Kaiserschnitt eingesetzt; ausserhalb der Geburtshilfe in der Schwangerschaft nur nach ärztlicher Abwägung.","stillzeit":"Der Übergang in die Muttermilch ist beim Menschen nicht untersucht; die zu erwartende Menge ist gering, Stillen ist nach Rücksprache in der Regel möglich.","hinweise":["Nach einer rückenmarknahen Betäubung können Gefühl und Kraft in den Beinen über Stunden fehlen – nur mit Hilfe aufstehen.","Blutverdünnende Medikamente und Fluvoxamin vor dem Eingriff angeben.","Taubheit um den Mund, Ohrensausen, Metallgeschmack oder Unruhe sofort melden (mögliche Zeichen einer Überdosierung)."],"darreichung":["Injektionslösung","Infusionslösung"]},"rosenwurz":{"wirkmechanismus":"Soll die Widerstandskraft gegenüber Stress stärken (Adaptogen). Der Trockenextrakt aus dem Wurzelstock der Rosenwurz enthält unter anderem Rosavine und Salidrosid. Diskutiert wird eine ausgleichende Wirkung auf die Stresshormon-Achse (Hypothalamus–Hypophyse–Nebenniere) und auf die Freisetzung von Stressmediatoren; der genaue Wirkmechanismus ist nicht geklärt.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen (z. B. Hautausschlag, Juckreiz)"]},"schwangerschaft":"Mangels ausreichender Daten nicht empfohlen.","stillzeit":"Mangels ausreichender Daten nicht empfohlen.","hinweise":["Bessern sich die Beschwerden nach 2 Wochen nicht oder verschlechtern sie sich, ärztlichen Rat einholen."],"darreichung":["Filmtabletten"]},"rosskastaniensamen-extrakt":{"wirkmechanismus":"Dichtet die Venenwände ab und vermindert Schwellungen in den Beinen. Der Hauptwirkstoff Aescin, ein Gemisch aus Triterpensaponinen, senkt die Durchlässigkeit der Kapillaren, hemmt gewebeabbauende Enzyme in der Gefässwand und erhöht die Spannung der Venenwand. Dadurch tritt weniger Flüssigkeit ins Gewebe aus.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Übelkeit, Magendruck)","Schwindel, Kopfschmerzen","Juckreiz und allergische Hautreaktionen"]},"schwangerschaft":"Keine ausreichenden Daten; in der Schwangerschaft nicht empfohlen.","stillzeit":"Keine ausreichenden Daten; in der Stillzeit nicht empfohlen.","hinweise":["Tabletten unzerkaut mit Flüssigkeit, am besten zu einer Mahlzeit, einnehmen (bessere Magenverträglichkeit).","Die Wirkung setzt erst nach einigen Wochen regelmässiger Einnahme ein.","Kompressionsstrümpfe und Bewegung bleiben wichtig; bei plötzlicher, einseitiger Beinschwellung mit Schmerzen sofort ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"rosuvastatin":{"wirkmechanismus":"Senkt das Cholesterin, indem es dessen Herstellung in der Leber bremst. Rosuvastatin hemmt selektiv und kompetitiv die HMG-CoA-Reduktase, das Schlüsselenzym der Cholesterinsynthese; die Leberzellen bilden mehr LDL-Rezeptoren und holen vermehrt LDL-Cholesterin aus dem Blut. Es ist wasserlöslich, wird kaum verstoffwechselt (gering über CYP2C9) und vor allem über Transporter (OATP1B1 in die Leber, BCRP) aufgenommen bzw. ausgeschieden – Transporterhemmer sind deshalb wichtiger als CYP3A4-Hemmer. Bei Menschen asiatischer Herkunft sind die Blutspiegel etwa doppelt so hoch.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Verstopfung, Übelkeit, Bauchschmerzen","Myalgie (Muskelschmerzen)","Asthenie (Schwäche)","Diabetes mellitus bei Personen mit Risikofaktoren"],"gelegentlich":["Juckreiz, Hautausschlag, Nesselsucht"],"selten":["Myopathie (inkl. Myositis), Rhabdomyolyse (Muskelzerfall), Muskelriss","Lupusähnliches Syndrom","Überempfindlichkeitsreaktionen inkl. Angioödem","Pankreatitis (Bauchspeicheldrüsenentzündung)","Erhöhte Leberwerte (Transaminasen)","Thrombozytopenie (Mangel an Blutplättchen)"],"sehrSelten":["Gelbsucht, Hepatitis","Polyneuropathie, Gedächtnisverlust","Gelenkschmerzen","Hämaturie (Blut im Urin)","Gynäkomastie (Brustvergrösserung beim Mann)"],"unbekannt":["Stevens-Johnson-Syndrom, DRESS (schwere Arzneimittelreaktion mit Eosinophilie)","Immunvermittelte nekrotisierende Myopathie, Sehnenschäden","Depression, Schlafstörungen (inkl. Albträume), periphere Neuropathie","Husten, Atemnot, Durchfall, Ödeme","Myasthenia gravis (Muskelschwäche) oder deren Verschlechterung"]},"schwangerschaft":"Kontraindiziert – Cholesterin ist für die Entwicklung des Ungeborenen nötig. Frauen im gebärfähigen Alter müssen zuverlässig verhüten; bei Eintritt einer Schwangerschaft sofort absetzen.","stillzeit":"Kontraindiziert – Rosuvastatin geht bei Tieren in die Milch über; Daten beim Menschen fehlen.","hinweise":["Einmal täglich zu einer beliebigen, aber gleichbleibenden Tageszeit, mit oder ohne Essen.","Unerklärliche Muskelschmerzen, -schwäche oder -krämpfe, besonders mit Fieber oder dunklem Urin, sofort ärztlich melden.","Magensäurebinder (Antazida) frühestens 2 Stunden nach Rosuvastatin einnehmen.","Leberwerte vor Behandlungsbeginn kontrollieren; Ernährung und Bewegung bleiben wichtig."],"darreichung":["Filmtabletten"]},"rotavirus-impfstoff":{"wirkmechanismus":"Schützt Säuglinge vor schwerem Brechdurchfall, indem das Immunsystem den Erreger schon im Darm erkennen lernt. Der Impfstoff enthält lebende, abgeschwächte menschliche Rotaviren (Stamm RIX4414), die geschluckt werden und sich im Darm vermehren. Dies löst eine Antikörperbildung in der Darmschleimhaut und im Blut aus, die vor allem gegen schwere Verläufe schützt. Das Impfvirus wird einige Tage mit dem Stuhl ausgeschieden.","nebenwirkungen":{"haeufig":["Durchfall","Reizbarkeit"],"gelegentlich":["Bauchschmerzen","Blähungen","Hautentzündung (Dermatitis)"],"sehrSelten":["Invagination (Darmeinstülpung), vor allem in der ersten Woche nach der ersten Dosis"],"unbekannt":["Blut im Stuhl (Hämatochezie)","Schwere Durchfallerkrankung mit dem Impfvirus bei Säuglingen mit SCID"]},"schwangerschaft":"Nicht zutreffend – der Impfstoff ist nur für Säuglinge bestimmt.","stillzeit":"Das geimpfte Kind darf vor und nach der Impfung normal gestillt werden; der Impfschutz wird dadurch nicht vermindert.","hinweise":["Wird geschluckt, niemals gespritzt. Spuckt das Kind den Grossteil der Dosis aus, kann beim gleichen Termin einmal nachgegeben werden.","Erste Dosis ab 6 Wochen; die Impfserie (2 Dosen) bis spätestens zur 24. Lebenswoche abschliessen.","Bei starken Bauchschmerzen, anhaltendem Erbrechen, Blut im Stuhl oder aufgeblähtem Bauch – v. a. in der ersten Woche nach der Impfung – sofort ärztliche Hilfe holen.","Nach dem Wickeln gründlich Hände waschen (Impfvirus im Stuhl)."],"darreichung":["Suspension zum Einnehmen (Applikator)"]},"rotes-weinlaub-extrakt":{"wirkmechanismus":"Dichtet die Wände kleiner Blutgefässe ab und vermindert so Schwellungen in den Beinen. Die im Extrakt enthaltenen Flavonoide (v. a. Quercetin-Glucuronid und Isoquercitrin) wirken antioxidativ und entzündungshemmend, schützen die Gefässinnenwand (Endothel) und senken die Durchlässigkeit der Kapillaren. Dadurch tritt weniger Flüssigkeit ins Gewebe aus.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden, Übelkeit, Verdauungsstörungen","Kopfschmerzen","Hautreaktionen (Juckreiz, Rötung, Nesselsucht)","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Keine ausreichenden Daten; in der Schwangerschaft nicht empfohlen.","stillzeit":"Keine ausreichenden Daten; in der Stillzeit nicht empfohlen.","hinweise":["Die Wirkung setzt erst nach mehreren Wochen regelmässiger Einnahme ein.","Kompressionsstrümpfe, Bewegung und Hochlagern der Beine bleiben wichtige Massnahmen.","Bei plötzlicher, einseitiger Beinschwellung mit Schmerzen sofort ärztlich abklären lassen (Thrombose)."],"darreichung":["Filmtabletten"]},"rotigotin":{"wirkmechanismus":"Ahmt im Gehirn die Wirkung des Botenstoffs Dopamin nach und wird gleichmässig über die Haut aufgenommen. Rotigotin ist ein nicht-ergoliner Dopaminagonist, der vor allem D3-, D2- und D1-Rezeptoren stimuliert. Durch die kontinuierliche Abgabe aus dem Pflaster über 24 Stunden entstehen stabile Wirkstoffspiegel, was auch nächtliche und morgendliche Beschwerden lindern kann.","nebenwirkungen":{"sehrHaeufig":["Hautreaktionen an der Klebestelle (Rötung, Juckreiz, Reizung)","Übelkeit","Schläfrigkeit","Schwindel","Kopfschmerzen"],"haeufig":["Plötzliches Einschlafen, Schlafstörungen, abnorme Träume","Halluzinationen","Impulskontrollstörungen (Spielsucht, Kaufsucht, Essattacken, gesteigertes sexuelles Verlangen)","Erbrechen, Verstopfung, Mundtrockenheit, Verdauungsbeschwerden","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Bluthochdruck","Dyskinesien, Ohnmacht","Beinödeme, Schwäche, Gewichtsabnahme","Juckreiz und vermehrtes Schwitzen am ganzen Körper"],"gelegentlich":["Vorhofflimmern, Herzrasen","Verschwommenes Sehen","Verwirrtheit, Zwangsstörungen"],"selten":["Psychotische Störungen, Wahn, Delir, aggressives Verhalten","Krampfanfälle","Generalisierter Hautausschlag"],"unbekannt":["Dopamin-Dysregulationssyndrom","Dopaminagonisten-Entzugssyndrom (Apathie, Angst, Depression, Schmerzen beim Absetzen)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen. In der Schwangerschaft nicht anwenden.","stillzeit":"Rotigotin hemmt die Milchbildung und geht wahrscheinlich in die Muttermilch über. Nicht stillen.","hinweise":["Pflaster täglich zur gleichen Zeit wechseln und an einer anderen Hautstelle aufkleben; dieselbe Stelle erst nach 14 Tagen wieder verwenden.","Wärme auf dem Pflaster meiden (Sauna, heisses Bad, Heizkissen, direkte Sonne).","Vor MRT oder Kardioversion das Pflaster entfernen.","Nicht abrupt absetzen; bei Tagesschläfrigkeit oder plötzlichem Einschlafen nicht Auto fahren."],"darreichung":["Transdermales Pflaster"]},"rozanolixizumab":{"wirkmechanismus":"Senkt die Menge an Antikörpern im Blut – auch jener, die bei Myasthenia gravis die Signalübertragung zwischen Nerv und Muskel stören. Rozanolixizumab ist ein humanisierter monoklonaler IgG4-Antikörper, der den neonatalen Fc-Rezeptor (FcRn) blockiert. FcRn schützt normalerweise IgG-Antikörper vor dem Abbau und führt sie in den Blutkreislauf zurück. Ist er blockiert, werden IgG-Antikörper einschliesslich der Autoantikörper beschleunigt abgebaut; andere Antikörperklassen wie IgA und IgM bleiben weitgehend unbeeinflusst.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (inkl. Migräne)","Durchfall"],"haeufig":["Fieber","Gelenkschmerzen","Hautausschlag","Reaktionen an der Infusionsstelle"],"unbekannt":["Aseptische Meningitis (nicht bakterielle Hirnhautentzündung)","Infektionen"]},"schwangerschaft":"Nur anwenden, wenn der Nutzen das Risiko klar überwiegt. Der Wirkstoff kann den Übertritt mütterlicher Schutzantikörper auf das Kind vermindern; Impfungen beim Säugling ärztlich besprechen.","stillzeit":"Keine Daten; über Stillen ist ärztlich zu entscheiden.","hinweise":["Starke Kopfschmerzen mit Fieber, Nackensteifigkeit, Übelkeit oder Lichtempfindlichkeit sofort melden.","Impfungen vor Beginn eines Behandlungszyklus aktualisieren.","Behandlung mit anderen Antikörpern oder Immunglobulinen immer angeben."],"darreichung":["Injektionslösung zur subkutanen Infusion"]},"rsv-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Antikörper gegen das RS-Virus zu bilden, das vor allem bei Säuglingen und älteren Menschen schwere Atemwegsinfekte auslöst. Die Impfstoffe enthalten das gentechnisch hergestellte Fusionsprotein F des Virus in seiner stabilisierten Präfusions-Form, gegen die besonders wirksame neutralisierende Antikörper entstehen. Arexvy enthält zusätzlich den Wirkverstärker AS01E, Abrysvo die F-Proteine der Subtypen A und B ohne Wirkverstärker. Bei der Impfung in der Schwangerschaft gehen die mütterlichen Antikörper über die Plazenta auf das Kind über.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Einstichstelle","Müdigkeit","Kopfschmerzen","Muskel- und Gelenkschmerzen"],"haeufig":["Rötung und Schwellung an der Einstichstelle","Fieber, Schüttelfrost"],"gelegentlich":["Lymphknotenschwellung","Übelkeit, Bauchschmerzen, Erbrechen","Juckreiz an der Einstichstelle","Hautausschlag"],"unbekannt":["Guillain-Barré-Syndrom (Nervenentzündung mit Lähmungen)","Schwere allergische Reaktionen"]},"schwangerschaft":"Abrysvo ist zur Impfung in der Schwangerschaft zum Schutz des Neugeborenen zugelassen; in Studien traten etwas mehr Frühgeburten auf, ein Zusammenhang ist nicht belegt. Arexvy ist für Schwangere nicht vorgesehen.","stillzeit":"Keine Daten; Impfung in der Stillzeit nur nach ärztlicher Abwägung.","hinweise":["In der Schweiz vor allem für ältere Menschen und Erwachsene mit Risikofaktoren empfohlen, am besten im Herbst vor der RSV-Saison.","Nach heutigem Stand wird eine einzelne Dosis gegeben; ob eine Auffrischung nötig ist, wird noch untersucht.","Säuglinge können statt über die Impfung der Mutter auch mit dem Antikörper Nirsevimab geschützt werden."],"darreichung":["Pulver und Suspension bzw. Lösungsmittel zur Herstellung einer Injektionssuspension"]},"rucaparib":{"wirkmechanismus":"Verhindert, dass Krebszellen Schäden an ihrem Erbgut reparieren. Rucaparib hemmt die Enzyme PARP-1, PARP-2 und PARP-3, die an der Reparatur von DNA-Einzelstrangbrüchen beteiligt sind, und hält PARP an der DNA fest. Tumorzellen mit Defekten der homologen Rekombination, etwa bei BRCA-Mutationen, können die entstehenden Doppelstrangbrüche nicht beheben und sterben ab.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen","Müdigkeit, Schwäche","Anämie, Thrombozytopenie, Neutropenie","Erhöhte Leberwerte (ALT, AST)","Erhöhtes Kreatinin (Nierenwert)","Geschmacksstörungen","Appetitlosigkeit","Durchfall, Verstopfung, Bauchschmerzen"],"haeufig":["Lichtempfindlichkeit der Haut","Hautausschlag, Juckreiz","Atemnot","Flüssigkeitsmangel (Dehydratation)"],"unbekannt":["Myelodysplastisches Syndrom / akute myeloische Leukämie (Blutkrebs)"]},"schwangerschaft":"Nicht anwenden. Schwangerschaftstest vor Beginn; wirksame Verhütung während und bis 6 Monate nach der letzten Dosis.","stillzeit":"Kontraindiziert; während der Behandlung und bis 2 Wochen nach der letzten Dosis nicht stillen.","hinweise":["Zweimal täglich im Abstand von etwa 12 Stunden einnehmen, mit oder ohne Essen.","Direkte Sonne meiden und Sonnenschutz mit hohem Schutzfaktor verwenden.","Blutbild und Leberwerte regelmässig kontrollieren lassen."],"darreichung":["Filmtabletten"]},"rufinamid":{"wirkmechanismus":"Beruhigt überaktive Nervenzellen im Gehirn. Rufinamid verlängert den inaktiven Zustand spannungsabhängiger Natriumkanäle und begrenzt so die rasche, wiederholte Entladung von Nervenzellen, über die sich Anfälle ausbreiten. Chemisch ist es ein Triazol-Derivat und mit anderen Antiepileptika nicht verwandt.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit","Kopfschmerzen","Schwindel","Übelkeit, Erbrechen","Müdigkeit"],"haeufig":["Infekte der Atemwege, Lungenentzündung, Ohren- und Nasennebenhöhlenentzündung","Appetitlosigkeit, Gewichtsabnahme","Angst, Schlaflosigkeit","Status epilepticus (anhaltender Krampfanfall), Krampfanfälle","Koordinations- und Gangstörungen, Nystagmus (Augenzittern), Zittern","Doppelbilder, verschwommenes Sehen","Bauchschmerzen, Verstopfung, Durchfall, Verdauungsbeschwerden","Hautausschlag, Akne"],"gelegentlich":["Überempfindlichkeitsreaktionen, auch mit Fieber, Ausschlag und Organbeteiligung (DRESS)","Erhöhte Leberwerte"],"unbekannt":["Verkürzung der QT-Zeit im EKG"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung. Frauen im gebärfähigen Alter sollen zuverlässig verhüten – hormonale Verhütung kann abgeschwächt sein.","stillzeit":"Es ist nicht bekannt, ob Rufinamid in die Muttermilch übergeht; Stillen nur nach ärztlicher Abwägung.","hinweise":["Mit dem Essen einnehmen.","Nicht abrupt absetzen; die Dosis wird schrittweise reduziert.","Bei Fieber mit Hautausschlag sofort ärztlich abklären.","Kann Reaktionsvermögen und Fahrtüchtigkeit beeinträchtigen; Alkohol meiden."],"darreichung":["Filmtabletten","Suspension zum Einnehmen"]},"ruxolitinib":{"wirkmechanismus":"Bremst überaktive Signalwege der Blutbildung und des Immunsystems. Ruxolitinib hemmt selektiv die Januskinasen JAK1 und JAK2, die Signale von Zytokinen und Wachstumsfaktoren über den JAK-STAT-Weg ins Zellinnere weiterleiten. Bei Myelofibrose und Polycythaemia vera ist dieser Weg (oft durch eine JAK2-Mutation) dauerhaft aktiviert; die Hemmung verkleinert die Milz und lindert Beschwerden wie Nachtschweiss und Juckreiz. Bei Vitiligo und Graft-versus-Host-Krankheit dämpft es T-Zellen, die Pigmentzellen bzw. körpereigenes Gewebe angreifen.","nebenwirkungen":{"sehrHaeufig":["Anämie, Thrombozytopenie, Neutropenie (Blutbildveränderungen)","Blutergüsse (Hämatome) und andere Blutungen","Harnwegsinfektionen","Schwindel, Kopfschmerzen","Gewichtszunahme, erhöhte Blutfette (Cholesterin, Triglyceride)","Erhöhte Leberwerte","Bluthochdruck","Verstopfung"],"haeufig":["Gürtelrose (Herpes zoster), Lungenentzündung","Magen-Darm-Blutungen, Hirnblutung","Blähungen","Akne und Juckreiz an der Auftragsstelle (Creme)"],"gelegentlich":["Tuberkulose"],"unbekannt":["Wiederaufflammen einer Hepatitis B","Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","Heller Hautkrebs (nicht-melanozytärer Hautkrebs)"]},"schwangerschaft":"Kontraindiziert, auch die Creme. Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Blutbild vor Beginn und regelmässig während der Behandlung kontrollieren lassen.","Tabletten nicht eigenmächtig absetzen: Beschwerden der Myelofibrose können innerhalb etwa einer Woche zurückkehren; das Absetzen erfolgt schrittweise nach ärztlicher Anweisung.","Creme nur auf höchstens 10 % der Körperoberfläche auftragen; die Repigmentierung braucht oft mehrere Monate.","Fieber, Infektzeichen, Bläschenausschlag oder neue neurologische Beschwerden umgehend ärztlich melden."],"darreichung":["Tabletten","Creme"]}});
